// Text of the /help page in all 16 languages (moved out of its client component on
// 2026-10-22). /{locale}/help hands the view one language (lib/localize-data.ts); only the
// unprefixed /help, whose language is known only in the browser, sends all of them.
import type { GlyphName } from '@/components/ToolGlyph';

export type LocaleContent = Record<string, string>;

export interface HelpItem {
  key: string;
  href: string;
  /** Only items that do not point at a tool; a tool item shows that tool's own icon. */
  icon?: GlyphName;
  q: LocaleContent;
  a: LocaleContent;
}

export interface HelpCategory {
  key: string;
  icon: GlyphName;
  label: Record<string, string>;
  items: HelpItem[];
}

export const helpData: HelpCategory[] = [
  {
    key: 'general', icon: 'info',
    label: { pl: 'Problemy ogólne', en: 'General Issues' , de: 'Allgemeine Probleme', es: 'Problemas generales', pt: 'Problemas gerais', no: 'Generelle problemer', sv: 'Allmänna problem', fr: 'Problèmes généraux', ar: 'مشاكل عامة', fa: 'مشکلات عمومی', tr: 'Genel Sorunlar', hi: 'सामान्य समस्याएं', is: 'Almenn vandamál', it: 'Problemi generali', ja: '一般的な問題', zh: '常见问题'},
    items: [
      { key: 'largefile', href: '#', icon: 'bigFile',
        q: { pl: 'Plik PDF jest za duży i nie chce się załadować?', en: 'The PDF file is too large and won\'t load?' , de: 'Die PDF-Datei ist zu groß und lässt sich nicht laden?', es: '¿El archivo PDF es demasiado grande y no se carga?', pt: 'O ficheiro PDF é demasiado grande e não carrega?', no: 'PDF-filen er for stor og vil ikke lastes inn?', sv: 'Är PDF-filen för stor och laddas inte?', fr: 'Le fichier PDF est trop volumineux et ne se charge pas ?', ar: 'ملف PDF كبير جدًا ولا يتم تحميله؟', fa: 'فایل PDF خیلی بزرگ است و بارگذاری نمی‌شود؟', tr: 'PDF dosyası çok büyük ve yüklenmiyor mu?', hi: 'क्या PDF फ़ाइल बहुत बड़ी है और लोड नहीं हो रही है?', is: 'Er PDF-skráin of stór og hleðst ekki?', it: 'Il file PDF è troppo grande e non si carica?', ja: 'PDFファイルが大きすぎて読み込めませんか？', zh: 'PDF文件过大无法加载？'},
        a: { pl: 'Jeśli plik ma kilkadziesiąt MB i strona działa wolno, spróbuj: (1) otworzyć plik w lżejszej przeglądarce (Chrome lub Edge). (2) Zamknąć inne karty, aby zwolnić pamięć RAM. (3) Użyć mniejszego pliku lub najpierw skompresować go za pomocą narzędzia Kompresuj PDF. (4) W ostateczności podzielić duży plik na mniejsze części przed przetwarzaniem.', en: 'If the file is several dozen MB and the page runs slow, try: (1) Open the file in a lighter browser (Chrome or Edge). (2) Close other tabs to free up RAM. (3) Use a smaller file or first compress it with the Compress PDF tool. (4) As a last resort, split the large file into smaller parts before processing.' , de: 'Wenn die Datei mehrere Dutzend MB groß ist und die Seite langsam läuft, versuchen Sie Folgendes: (1) Öffnen Sie die Datei in einem leichteren Browser (Chrome oder Edge). (2) Schließen Sie andere Tabs, um Arbeitsspeicher freizugeben. (3) Verwenden Sie eine kleinere Datei oder komprimieren Sie sie zuerst mit dem Werkzeug „PDF komprimieren“. (4) Teilen Sie die große Datei im Notfall vor der Verarbeitung in kleinere Teile.', es: 'Si el archivo pesa varias decenas de MB y la página va lenta, pruebe a: (1) abrir el archivo en un navegador más ligero (Chrome o Edge). (2) Cerrar otras pestañas para liberar memoria RAM. (3) Usar un archivo más pequeño o comprimirlo primero con la herramienta «Comprimir PDF». (4) Como último recurso, dividir el archivo grande en partes más pequeñas antes de procesarlo.', pt: 'Se o ficheiro tiver várias dezenas de MB e a página funcionar lentamente, tente: (1) abrir o ficheiro num navegador mais leve (Chrome ou Edge). (2) Fechar outros separadores para libertar memória RAM. (3) Utilizar um ficheiro mais pequeno ou comprimi-lo primeiro com a ferramenta «Comprimir PDF». (4) Em última instância, dividir o ficheiro grande em partes mais pequenas antes de o processar.', no: 'Hvis filen er på flere titalls MB og siden går tregt, prøv følgende: (1) Åpne filen i en lettere nettleser (Chrome eller Edge). (2) Lukk andre faner for å frigjøre RAM-minne. (3) Bruk en mindre fil, eller komprimer den først med verktøyet «Komprimer PDF». (4) Som en siste utvei, del den store filen i mindre deler før du behandler den.', sv: 'Om filen är flera tiotals MB och sidan går långsamt, prova följande: (1) Öppna filen i en lättare webbläsare (Chrome eller Edge). (2) Stäng andra flikar för att frigöra RAM-minne. (3) Använd en mindre fil eller komprimera den först med verktyget ”Komprimera PDF”. (4) Som en sista utväg, dela upp den stora filen i mindre delar innan du bearbetar den.', fr: 'Si le fichier fait plusieurs dizaines de Mo et que la page est lente, essayez ceci : (1) Ouvrez le fichier dans un navigateur plus léger (Chrome ou Edge). (2) Fermez les autres onglets pour libérer de la RAM. (3) Utilisez un fichier plus petit ou compressez-le d\'abord avec l\'outil « Compresser PDF ». (4) En dernier recours, divisez le fichier volumineux en plusieurs parties avant de le traiter.', ar: 'إذا كان حجم الملف عشرات الميغابايت وكانت الصفحة بطيئة، جرّب ما يلي: (1) افتح الملف في متصفح أخف (Chrome أو Edge). (2) أغلق علامات التبويب الأخرى لتحرير ذاكرة الوصول العشوائي (RAM). (3) استخدم ملفًا أصغر أو اضغطه أولاً باستخدام أداة "ضغط PDF". (4) كحل أخير، قسّم الملف الكبير إلى أجزاء أصغر قبل المعالجة.', fa: 'اگر حجم فایل چند ده مگابایت است و صفحه به کندی کار می‌کند، این کارها را امتحان کنید: (1) فایل را در یک مرورگر سبک‌تر باز کنید (Chrome یا Edge). (2) تب‌های دیگر را ببندید تا RAM آزاد شود. (3) از یک فایل کوچک‌تر استفاده کنید یا ابتدا آن را با ابزار "فشرده‌سازی PDF" فشرده کنید. (4) به عنوان آخرین راه، فایل بزرگ را قبل از پردازش به بخش‌های کوچک‌تر تقسیم کنید.', tr: 'Dosya onlarca MB boyutundaysa ve sayfa yavaş çalışıyorsa şunları deneyin: (1) Dosyayı daha hafif bir tarayıcıda açın (Chrome veya Edge). (2) RAM\'i boşaltmak için diğer sekmeleri kapatın. (3) Daha küçük bir dosya kullanın veya önce PDF Sıkıştır aracıyla sıkıştırın. (4) Son çare olarak, büyük dosyayı işlemeden önce daha küçük parçalara bölün.', hi: 'यदि फ़ाइल कई दर्जन MB की है और पृष्ठ धीरे चलता है, तो प्रयास करें: (1) फ़ाइल को हल्के ब्राउज़र (Chrome या Edge) में खोलें। (2) RAM खाली करने के लिए अन्य टैब बंद करें। (3) छोटी फ़ाइल का उपयोग करें या पहले इसे PDF संपीड़ित करें उपकरण से संपीड़ित करें। (4) अंतिम उपाय के रूप में, प्रसंस्करण से पहले बड़ी फ़ाइल को छोटे भागों में विभाजित करें।', is: 'Ef skráin er nokkur tugir MB að stærð og síðan virkar hægt skaltu prófa: (1) Opnaðu skrána í léttari vafra (Chrome eða Edge). (2) Lokaðu öðrum flipum til að losa um vinnsluminni. (3) Notaðu minni skrá eða þjappaðu henni fyrst með tólinu Þjappa PDF. (4) Sem síðasta úrræði skaltu skipta stóru skránni í smærri hluta fyrir vinnslu.', it: 'Se il file pesa diverse decine di MB e la pagina è lenta, prova: (1) ad aprire il file in un browser più leggero (Chrome o Edge). (2) Chiudi le altre schede per liberare RAM. (3) Usa un file più piccolo o comprimilo prima con lo strumento Comprimere PDF. (4) Come ultima risorsa, dividi il file grande in parti più piccole prima dell\'elaborazione.', ja: 'ファイルが数十MBあり、ページの動作が遅い場合は、以下をお試しください：（1）軽量なブラウザ（ChromeまたはEdge）でファイルを開いてください。（2）他のタブを閉じてRAMを解放してください。（3）より小さいファイルを使用するか、先に「PDF圧縮」ツールで圧縮してください。（4）最後の手段として、処理前に大きなファイルを複数の小さな部分に分割してください。', zh: '如果文件有几十MB且页面运行缓慢，请尝试：（1）用更轻量的浏览器（Chrome或Edge）打开文件。（2）关闭其他标签页以释放内存。（3）使用较小的文件，或先用“压缩PDF”工具压缩文件。（4）如果万不得已，请将大文件拆分成更小的部分后再处理。'},
      },
      { key: 'notpdf', href: '#', icon: 'fileX',
        q: { pl: 'Plik nie jest rozpoznawany jako PDF?', en: 'File is not recognized as PDF?' , de: 'Die Datei wird nicht als PDF erkannt?', es: '¿El archivo no se reconoce como PDF?', pt: 'O ficheiro não é reconhecido como PDF?', no: 'Filen blir ikke gjenkjent som PDF?', sv: 'Filen känns inte igen som PDF?', fr: 'Le fichier n\'est pas reconnu comme PDF ?', ar: 'لا يتم التعرف على الملف كملف PDF؟', fa: 'فایل به عنوان PDF شناسایی نمی‌شود؟', tr: 'Dosya PDF olarak tanınmıyor mu?', hi: 'क्या फ़ाइल को PDF के रूप में पहचाना नहीं जा रहा है?', is: 'Er skráin ekki viðurkennd sem PDF?', it: 'Il file non viene riconosciuto come PDF?', ja: 'ファイルがPDFとして認識されませんか？', zh: '文件无法被识别为PDF？'},
        a: { pl: 'Upewnij się, że plik ma rozszerzenie .pdf. Jeśli plik faktycznie jest PDF, ale nie chce się otworzyć, mógł zostać uszkodzony. Spróbuj otworzyć go w innym programie (Adobe Reader, przeglądarka). Jeśli działa w innych programach, zgłoś problem — możliwe, że plik używa niestandardowych funkcji PDF, które nie są obsługiwane.', en: 'Make sure the file has a .pdf extension. If the file is actually a PDF but won\'t open, it may be corrupted. Try opening it in another program (Adobe Reader, browser). If it works in other programs, report the issue — the file may use non-standard PDF features not yet supported.' , de: 'Stellen Sie sicher, dass die Datei die Erweiterung .pdf hat. Wenn die Datei tatsächlich eine PDF-Datei ist, sich aber nicht öffnen lässt, ist sie möglicherweise beschädigt. Versuchen Sie, sie in einem anderen Programm zu öffnen (Adobe Reader, Browser). Wenn sie in anderen Programmen funktioniert, melden Sie das Problem – die Datei verwendet möglicherweise nicht standardkonforme PDF-Funktionen, die noch nicht unterstützt werden.', es: 'Asegúrese de que el archivo tenga la extensión .pdf. Si el archivo es realmente un PDF pero no se abre, puede estar dañado. Intente abrirlo en otro programa (Adobe Reader, navegador). Si funciona en otros programas, informe del problema: el archivo puede usar funciones de PDF no estándar que aún no son compatibles.', pt: 'Certifique-se de que o ficheiro tem a extensão .pdf. Se o ficheiro for realmente um PDF, mas não abrir, pode estar corrompido. Tente abri-lo noutro programa (Adobe Reader, navegador). Se funcionar noutros programas, comunique o problema — o ficheiro pode utilizar funcionalidades de PDF não padrão que ainda não são suportadas.', no: 'Kontroller at filen har filtypen .pdf. Hvis filen faktisk er en PDF, men ikke vil åpne, kan den være skadet. Prøv å åpne den i et annet program (Adobe Reader, nettleser). Hvis den fungerer i andre programmer, rapporter problemet — filen kan bruke ikke-standard PDF-funksjoner som ennå ikke støttes.', sv: 'Kontrollera att filen har filtillägget .pdf. Om filen faktiskt är en PDF men inte öppnas kan den vara skadad. Försök att öppna den i ett annat program (Adobe Reader, webbläsare). Om den fungerar i andra program, rapportera problemet — filen kan använda icke-standard PDF-funktioner som ännu inte stöds.', fr: 'Assurez-vous que le fichier porte l\'extension .pdf. Si le fichier est bien un PDF mais ne s\'ouvre pas, il est peut-être corrompu. Essayez de l\'ouvrir dans un autre programme (Adobe Reader, navigateur). S\'il fonctionne dans d\'autres programmes, signalez le problème — le fichier peut utiliser des fonctionnalités PDF non standard qui ne sont pas encore prises en charge.', ar: 'تأكد من أن امتداد الملف هو .pdf. إذا كان الملف PDF فعليًا ولكنه لا يفتح، فقد يكون تالفًا. جرّب فتحه في برنامج آخر (Adobe Reader، المتصفح). إذا كان يعمل في برامج أخرى، أبلغ عن المشكلة — قد يستخدم الملف ميزات PDF غير قياسية غير مدعومة بعد.', fa: 'مطمئن شوید فایل پسوند .pdf دارد. اگر فایل واقعاً PDF است اما باز نمی‌شود، ممکن است خراب شده باشد. سعی کنید آن را در برنامه دیگری باز کنید (Adobe Reader، مرورگر). اگر در برنامه‌های دیگر کار می‌کند، مشکل را گزارش دهید — ممکن است فایل از ویژگی‌های PDF غیراستاندارد استفاده کند که هنوز پشتیبانی نمی‌شوند.', tr: 'Dosyanın .pdf uzantılı olduğundan emin olun. Dosya gerçekten PDF ise ancak açılmıyorsa bozulmuş olabilir. Başka bir programda açmayı deneyin (Adobe Reader, tarayıcı). Başka programlarda çalışıyorsa sorunu bildirin — dosya henüz desteklenmeyen standart dışı PDF özellikleri kullanıyor olabilir.', hi: 'सुनिश्चित करें कि फ़ाइल का एक्सटेंशन .pdf है। यदि फ़ाइल वास्तव में PDF है लेकिन खुलती नहीं है, तो वह दूषित हो सकती है। इसे किसी अन्य प्रोग्राम (Adobe Reader, ब्राउज़र) में खोलने का प्रयास करें। यदि यह अन्य प्रोग्रामों में काम करती है, तो समस्या की रिपोर्ट करें - फ़ाइल गैर-मानक PDF सुविधाओं का उपयोग कर सकती है जो अभी तक समर्थित नहीं हैं।', is: 'Gakktu úr skugga um að skráin hafi .pdf-endingu. Ef skráin er í raun PDF en opnast ekki getur hún verið skemmd. Prófaðu að opna hana í öðru forriti (Adobe Reader, vafra). Ef hún virkar í öðrum forritum skaltu tilkynna vandamálið — skráin gæti notað óstöðluð PDF-eiginleika sem ekki er enn stutt.', it: 'Assicurati che il file abbia l\'estensione .pdf. Se il file è effettivamente un PDF ma non si apre, potrebbe essere danneggiato. Prova ad aprirlo con un altro programma (Adobe Reader, browser). Se funziona con altri programmi, segnala il problema: il file potrebbe utilizzare funzionalità PDF non standard non ancora supportate.', ja: 'ファイルの拡張子が.pdfであることを確認してください。ファイルが実際にはPDFであるにもかかわらず開けない場合は、破損している可能性があります。別のプログラム（Adobe Reader、ブラウザ）で開いてみてください。他のプログラムで開ける場合は、問題をお知らせください。ファイルがまだサポートされていない非標準のPDF機能を使用している可能性があります。', zh: '请确保文件具有.pdf扩展名。如果文件确实是PDF但无法打开，则文件可能已损坏。请尝试用其他程序（Adobe Reader、浏览器）打开它。如果文件在其他程序中可以正常打开，请报告该问题——文件可能使用了尚不支持的非标准PDF功能。'},
      },
      { key: 'memory', href: '#', icon: 'chip',
        q: { pl: 'Strona wyświetla błąd pamięci lub zawiesza się?', en: 'The page shows a memory error or freezes?' , de: 'Die Seite zeigt einen Speicherfehler oder friert ein?', es: '¿La página muestra un error de memoria o se congela?', pt: 'A página apresenta um erro de memória ou congela?', no: 'Siden viser en minnefeil eller fryser?', sv: 'Sidan visar ett minnesfel eller fryser?', fr: 'La page affiche une erreur de mémoire ou se fige ?', ar: 'تعرض الصفحة خطأ في الذاكرة أو تتجمد؟', fa: 'صفحه خطای حافظه نشان می‌دهد یا قفل می‌کند؟', tr: 'Sayfa bellek hatası gösteriyor veya donuyor mu?', hi: 'क्या पृष्ठ मेमोरी त्रुटि दिखाता है या फ़्रीज़ हो जाता है?', is: 'Sýnir síðan minnisvillu eða frýs?', it: 'La pagina mostra un errore di memoria o si blocca?', ja: 'ページにメモリエラーが表示されたり、フリーズしたりしますか？', zh: '页面显示内存错误或卡死？'},
        a: { pl: 'Narzędzia działają w całości w przeglądarce, więc duże pliki mogą przekroczyć dostępną pamięć RAM. Rozwiązania: (1) Użyj przeglądarki Chrome/Edge — mają lepszą obsługę pamięci. (2) Zamknij inne programy i karty. (3) Przetwarzaj mniejsze pliki. (4) Jeśli problem występuje stale, spróbuj zaktualizować przeglądarkę.', en: 'All tools run entirely in the browser, so large files may exceed available RAM. Solutions: (1) Use Chrome/Edge — they handle memory better. (2) Close other programs and tabs. (3) Process smaller files. (4) If the issue persists, try updating your browser.' , de: 'Alle Werkzeuge laufen vollständig im Browser, sodass große Dateien den verfügbaren Arbeitsspeicher überschreiten können. Lösungen: (1) Verwenden Sie Chrome/Edge – sie verwalten den Speicher besser. (2) Schließen Sie andere Programme und Tabs. (3) Verarbeiten Sie kleinere Dateien. (4) Wenn das Problem weiterhin besteht, versuchen Sie, Ihren Browser zu aktualisieren.', es: 'Todas las herramientas se ejecutan por completo en el navegador, por lo que los archivos grandes pueden superar la memoria RAM disponible. Soluciones: (1) Use Chrome/Edge: gestionan mejor la memoria. (2) Cierre otros programas y pestañas. (3) Procese archivos más pequeños. (4) Si el problema continúa, intente actualizar su navegador.', pt: 'Todas as ferramentas funcionam inteiramente no navegador, pelo que os ficheiros grandes podem exceder a memória RAM disponível. Soluções: (1) utilize o Chrome/Edge — gerem melhor a memória. (2) Feche outros programas e separadores. (3) Processe ficheiros mais pequenos. (4) Se o problema persistir, tente atualizar o navegador.', no: 'Alle verktøy kjører helt i nettleseren, så store filer kan overstige tilgjengelig RAM-minne. Løsninger: (1) Bruk Chrome/Edge — de håndterer minnet bedre. (2) Lukk andre programmer og faner. (3) Behandle mindre filer. (4) Hvis problemet vedvarer, prøv å oppdatere nettleseren din.', sv: 'Alla verktyg körs helt i webbläsaren, så stora filer kan överstiga det tillgängliga RAM-minnet. Lösningar: (1) Använd Chrome/Edge — de hanterar minnet bättre. (2) Stäng andra program och flikar. (3) Bearbeta mindre filer. (4) Om problemet kvarstår, försök att uppdatera webbläsaren.', fr: 'Tous les outils fonctionnent entièrement dans le navigateur, donc les fichiers volumineux peuvent dépasser la RAM disponible. Solutions : (1) Utilisez Chrome/Edge — ils gèrent mieux la mémoire. (2) Fermez les autres programmes et onglets. (3) Traitez des fichiers plus petits. (4) Si le problème persiste, essayez de mettre à jour votre navigateur.', ar: 'تعمل جميع الأدوات بالكامل في المتصفح، لذا قد تتجاوز الملفات الكبيرة الذاكرة المتاحة (RAM). الحلول: (1) استخدم Chrome/Edge — فهما يتعاملان مع الذاكرة بشكل أفضل. (2) أغلق البرامج وعلامات التبويب الأخرى. (3) عالج ملفات أصغر. (4) إذا استمرت المشكلة، حاول تحديث متصفحك.', fa: 'همه ابزارها کاملاً در مرورگر اجرا می‌شوند، بنابراین فایل‌های بزرگ ممکن است از RAM موجود فراتر روند. راه‌حل‌ها: (1) از Chrome/Edge استفاده کنید — حافظه را بهتر مدیریت می‌کنند. (2) برنامه‌ها و تب‌های دیگر را ببندید. (3) فایل‌های کوچک‌تر را پردازش کنید. (4) اگر مشکل ادامه داشت، سعی کنید مرورگر خود را به‌روزرسانی کنید.', tr: 'Tüm araçlar tamamen tarayıcıda çalışır, bu nedenle büyük dosyalar mevcut RAM\'i aşabilir. Çözümler: (1) Chrome/Edge kullanın — belleği daha iyi yönetirler. (2) Diğer programları ve sekmeleri kapatın. (3) Daha küçük dosyaları işleyin. (4) Sorun devam ederse tarayıcınızı güncellemeyi deneyin.', hi: 'सभी उपकरण पूरी तरह से ब्राउज़र में चलते हैं, इसलिए बड़ी फ़ाइलें उपलब्ध RAM से अधिक हो सकती हैं। समाधान: (1) Chrome/Edge का उपयोग करें - वे मेमोरी को बेहतर संभालते हैं। (2) अन्य प्रोग्राम और टैब बंद करें। (3) छोटी फ़ाइलों को प्रक्रिया करें। (4) यदि समस्या बनी रहती है, तो अपने ब्राउज़र को अपडेट करने का प्रयास करें।', is: 'Öll verkfæri keyra alfarið í vafranum, þannig að stórar skrár geta farið yfir tiltækt vinnsluminni (RAM). Lausnir: (1) Notaðu Chrome/Edge — þau meðhöndla minnið betur. (2) Lokaðu öðrum forritum og flipum. (3) Vinnsluðu smærri skrár. (4) Ef vandamálið er viðvarandi skaltu prófa að uppfæra vafrann þinn.', it: 'Tutti gli strumenti funzionano interamente nel browser, quindi i file di grandi dimensioni potrebbero superare la RAM disponibile. Soluzioni: (1) usa Chrome/Edge: gestiscono meglio la memoria. (2) Chiudi altri programmi e schede. (3) Elabora file più piccoli. (4) Se il problema persiste, prova ad aggiornare il browser.', ja: 'すべてのツールは完全にブラウザ内で動作するため、大きなファイルは利用可能なRAMを超える可能性があります。解決策：（1）Chrome/Edgeを使用してください（メモリの処理に優れています）。（2）他のプログラムやタブを閉じてください。（3）より小さいファイルを処理してください。（4）問題が解決しない場合は、ブラウザを更新してみてください。', zh: '所有工具都在浏览器中完全运行，因此大文件可能会超出可用内存。解决方法：（1）使用Chrome/Edge——它们的内存管理更好。（2）关闭其他程序和标签页。（3）处理较小的文件。（4）如果问题持续存在，请尝试更新浏览器。'},
      },
      { key: 'save', href: '#', icon: 'floppy',
        q: { pl: 'Nie mogę zapisać wynikowego pliku?', en: 'Can\'t save the resulting file?' , de: 'Kann die resultierende Datei nicht gespeichert werden?', es: '¿No puede guardar el archivo resultante?', pt: 'Não consegue guardar o ficheiro resultante?', no: 'Kan du ikke lagre den resulterende filen?', sv: 'Kan du inte spara den resulterande filen?', fr: 'Impossible d\'enregistrer le fichier obtenu ?', ar: 'لا يمكن حفظ الملف الناتج؟', fa: 'نمی‌توانم فایل نهایی را ذخیره کنم؟', tr: 'Ortaya çıkan dosyayı kaydedemiyor musunuz?', hi: 'क्या परिणामी फ़ाइल सहेज नहीं सकते?', is: 'Get ég ekki vistað útkomuskrána?', it: 'Non riesci a salvare il file risultante?', ja: '結果のファイルを保存できませんか？', zh: '无法保存结果文件？'},
        a: { pl: 'Jeśli po przetworzeniu plik nie pobiera się automatycznie: (1) Sprawdź, czy przeglądarka nie blokuje pobierania (iconka w pasku adresu). (2) Kliknij przycisk pobierania ręcznie, jeśli jest dostępny. (3) Spróbuj użyć innej przeglądarki. (4) Upewnij się, że masz wystarczająco miejsca na dysku.', en: 'If the file doesn\'t download automatically after processing: (1) Check if your browser is blocking downloads (icon in the address bar). (2) Click the download button manually if available. (3) Try a different browser. (4) Make sure you have enough disk space.' , de: 'Wenn die Datei nach der Verarbeitung nicht automatisch heruntergeladen wird: (1) Prüfen Sie, ob Ihr Browser Downloads blockiert (Symbol in der Adressleiste). (2) Klicken Sie den Download-Button bei Bedarf manuell an. (3) Versuchen Sie einen anderen Browser. (4) Stellen Sie sicher, dass Sie genügend Speicherplatz auf der Festplatte haben.', es: 'Si el archivo no se descarga automáticamente después del procesamiento: (1) Compruebe si su navegador bloquea las descargas (icono en la barra de direcciones). (2) Haga clic manualmente en el botón de descarga si está disponible. (3) Pruebe con otro navegador. (4) Asegúrese de tener suficiente espacio en el disco.', pt: 'Se o ficheiro não for descarregado automaticamente após o processamento: (1) verifique se o navegador está a bloquear as descargas (ícone na barra de endereços). (2) Clique manualmente no botão de descarga, se estiver disponível. (3) Experimente um navegador diferente. (4) Certifique-se de que tem espaço em disco suficiente.', no: 'Hvis filen ikke lastes ned automatisk etter behandling: (1) Sjekk om nettleseren din blokkerer nedlastinger (ikon i adresselinjen). (2) Klikk på nedlastingsknappen manuelt hvis den er tilgjengelig. (3) Prøv en annen nettleser. (4) Kontroller at du har nok diskplass.', sv: 'Om filen inte laddas ner automatiskt efter bearbetning: (1) Kontrollera om webbläsaren blockerar nedladdningar (ikon i adressfältet). (2) Klicka på nedladdningsknappen manuellt om den finns. (3) Prova en annan webbläsare. (4) Kontrollera att du har tillräckligt med diskutrymme.', fr: 'Si le fichier ne se télécharge pas automatiquement après le traitement : (1) Vérifiez si votre navigateur bloque les téléchargements (icône dans la barre d\'adresse). (2) Cliquez manuellement sur le bouton de téléchargement s\'il est disponible. (3) Essayez un autre navigateur. (4) Assurez-vous d\'avoir suffisamment d\'espace disque.', ar: 'إذا لم يتم تنزيل الملف تلقائيًا بعد المعالجة: (1) تحقق مما إذا كان متصفحك يحظر التنزيلات (الأيقونة في شريط العناوين). (2) انقر على زر التنزيل يدويًا إذا كان متاحًا. (3) جرّب متصفحًا مختلفًا. (4) تأكد من وجود مساحة كافية على القرص.', fa: 'اگر فایل پس از پردازش به طور خودکار دانلود نمی‌شود: (1) بررسی کنید که آیا مرورگر شما دانلودها را مسدود می‌کند (آیکون در نوار آدرس). (2) اگر موجود است، روی دکمه دانلود به صورت دستی کلیک کنید. (3) مرورگر دیگری را امتحان کنید. (4) مطمئن شوید فضای کافی روی دیسک دارید.', tr: 'Dosya işlemeden sonra otomatik olarak inmezse: (1) Tarayıcınızın indirmeleri engelleyip engellemediğini kontrol edin (adres çubuğundaki simge). (2) Varsa indirme düğmesine elle tıklayın. (3) Farklı bir tarayıcı deneyin. (4) Yeterli disk alanınızın olduğundan emin olun.', hi: 'यदि प्रसंस्करण के बाद फ़ाइल स्वचालित रूप से डाउनलोड नहीं होती है: (1) जाँचें कि क्या आपका ब्राउज़र डाउनलोड को ब्लॉक कर रहा है (एड्रेस बार में आइकन)। (2) यदि उपलब्ध हो तो डाउनलोड बटन पर मैन्युअल रूप से क्लिक करें। (3) दूसरा ब्राउज़र आज़माएँ। (4) सुनिश्चित करें कि आपके पास पर्याप्त डिस्क स्थान है।', is: 'Ef skráin sækir sig ekki sjálfkrafa eftir vinnslu: (1) Athugaðu hvort vafrinn þinn lokaði á niðurhal (táknið í veffangastikunni). (2) Smelltu handvirkt á niðurhalstakkann ef hann er í boði. (3) Prófaðu annan vafra. (4) Gakktu úr skugga um að þú hafir nægt pláss á diski.', it: 'Se il file non viene scaricato automaticamente dopo l\'elaborazione: (1) controlla se il browser blocca i download (icona nella barra degli indirizzi). (2) Fai clic manualmente sul pulsante di download, se disponibile. (3) Prova un browser diverso. (4) Assicurati di avere abbastanza spazio su disco.', ja: '処理後にファイルが自動的にダウンロードされない場合は：（1）ブラウザがダウンロードをブロックしていないか確認してください（アドレスバーのアイコン）。（2）可能であれば、ダウンロードボタンを手動でクリックしてください。（3）別のブラウザを試してください。（4）ディスクの空き容量が十分にあることを確認してください。', zh: '如果处理完成后文件没有自动下载：（1）检查浏览器是否阻止了下载（地址栏中的图标）。（2）如果有下载按钮，请手动点击。（3）尝试使用其他浏览器。（4）确保有足够的磁盘空间。'},
      },
      { key: 'wrongbrowser', href: '#', icon: 'browser',
        q: { pl: 'Które przeglądarki są obsługiwane?', en: 'Which browsers are supported?' , de: 'Welche Browser werden unterstützt?', es: '¿Qué navegadores son compatibles?', pt: 'Que navegadores são suportados?', no: 'Hvilke nettlesere støttes?', sv: 'Vilka webbläsare stöds?', fr: 'Quels navigateurs sont pris en charge ?', ar: 'ما المتصفحات المدعومة؟', fa: 'کدام مرورگر‌ها پشتیبانی می‌شوند؟', tr: 'Hangi tarayıcılar destekleniyor?', hi: 'कौन से ब्राउज़र समर्थित हैं?', is: 'Hvaða vafrar eru studdir?', it: 'Quali browser sono supportati?', ja: '対応しているブラウザはどれですか？', zh: '支持哪些浏览器？'},
        a: { pl: 'Narzędzia działają w każdej nowoczesnej przeglądarce: Chrome, Edge, Firefox, Opera, Safari (wersje z ostatnich 2 lat). Najlepszą wydajność oferują Chrome i Edge. Starsze przeglądarki (Internet Explorer, stare wersje Safari) nie są obsługiwane.', en: 'The tools work in all modern browsers: Chrome, Edge, Firefox, Opera, Safari (versions from the last 2 years). Best performance is in Chrome and Edge. Older browsers (Internet Explorer, old Safari versions) are not supported.' , de: 'Die Werkzeuge funktionieren in allen modernen Browsern: Chrome, Edge, Firefox, Opera, Safari (Versionen der letzten 2 Jahre). Die beste Leistung bieten Chrome und Edge. Ältere Browser (Internet Explorer, alte Safari-Versionen) werden nicht unterstützt.', es: 'Las herramientas funcionan en todos los navegadores modernos: Chrome, Edge, Firefox, Opera, Safari (versiones de los últimos 2 años). El mejor rendimiento se obtiene en Chrome y Edge. Los navegadores antiguos (Internet Explorer, versiones antiguas de Safari) no son compatibles.', pt: 'As ferramentas funcionam em todos os navegadores modernos: Chrome, Edge, Firefox, Opera, Safari (versões dos últimos 2 anos). O melhor desempenho é obtido no Chrome e no Edge. Os navegadores mais antigos (Internet Explorer, versões antigas do Safari) não são suportados.', no: 'Verktøyene fungerer i alle moderne nettlesere: Chrome, Edge, Firefox, Opera, Safari (versjoner fra de siste 2 årene). Best ytelse får du i Chrome og Edge. Eldre nettlesere (Internet Explorer, gamle Safari-versjoner) støttes ikke.', sv: 'Verktygen fungerar i alla moderna webbläsare: Chrome, Edge, Firefox, Opera, Safari (versioner från de senaste 2 åren). Bäst prestanda får du i Chrome och Edge. Äldre webbläsare (Internet Explorer, gamla Safari-versioner) stöds inte.', fr: 'Les outils fonctionnent dans tous les navigateurs modernes : Chrome, Edge, Firefox, Opera, Safari (versions des 2 dernières années). Les meilleures performances sont obtenues avec Chrome et Edge. Les navigateurs plus anciens (Internet Explorer, anciennes versions de Safari) ne sont pas pris en charge.', ar: 'تعمل الأدوات في جميع المتصفحات الحديثة: Chrome وEdge وFirefox وOpera وSafari (الإصدارات من آخر عامين). أفضل أداء في Chrome وEdge. لا يتم دعم المتصفحات الأقدم (Internet Explorer، إصدارات Safari القديمة).', fa: 'ابزارها در همه مرورگر‌های مدرن کار می‌کنند: Chrome، Edge، Firefox، Opera، Safari (نسخه‌های 2 سال اخیر). بهترین عملکرد در Chrome و Edge است. مرورگر‌های قدیمی‌تر (Internet Explorer، نسخه‌های قدیمی Safari) پشتیبانی نمی‌شوند.', tr: 'Araçlar tüm modern tarayıcılarda çalışır: Chrome, Edge, Firefox, Opera, Safari (son 2 yılın sürümleri). En iyi performans Chrome ve Edge\'dedir. Daha eski tarayıcılar (Internet Explorer, eski Safari sürümleri) desteklenmez.', hi: 'उपकरण सभी आधुनिक ब्राउज़रों में काम करते हैं: Chrome, Edge, Firefox, Opera, Safari (पिछले 2 वर्षों के संस्करण)। सबसे अच्छा प्रदर्शन Chrome और Edge में होता है। पुराने ब्राउज़र (Internet Explorer, पुराने Safari संस्करण) समर्थित नहीं हैं।', is: 'Verkfærin virka í öllum nútíma vöfrum: Chrome, Edge, Firefox, Opera, Safari (útgáfur frá síðustu 2 árum). Besti árangurinn fæst í Chrome og Edge. Eldri vafrar (Internet Explorer, gamlar Safari-útgáfur) eru ekki studdir.', it: 'Gli strumenti funzionano in tutti i browser moderni: Chrome, Edge, Firefox, Opera, Safari (versioni degli ultimi 2 anni). Le migliori prestazioni si ottengono con Chrome e Edge. I browser più vecchi (Internet Explorer, vecchie versioni di Safari) non sono supportati.', ja: 'ツールはすべての最新ブラウザで動作します：Chrome、Edge、Firefox、Opera、Safari（過去2年以内のバージョン）。最も優れたパフォーマンスはChromeとEdgeで得られます。古いブラウザ（Internet Explorer、旧バージョンのSafari）はサポートされていません。', zh: '这些工具可在所有现代浏览器中运行：Chrome、Edge、Firefox、Opera、Safari（最近两年的版本）。Chrome和Edge的性能最佳。较旧的浏览器（Internet Explorer、旧版Safari）不受支持。'},
      },
    ],
  },
  {
    key: 'edit', icon: 'sliders',
    label: { pl: 'Edycja PDF', en: 'Edit PDF' , de: 'PDF bearbeiten', es: 'Editar PDF', pt: 'Edição PDF', no: 'PDF-redigering', sv: 'PDF-redigering', fr: 'Édition PDF', ar: 'تحرير PDF', fa: 'ویرایش PDF', tr: 'PDF Düzenleme', hi: 'PDF संपादन', is: 'PDF breyting', it: 'Modifica PDF', ja: 'PDF編集', zh: 'PDF编辑'},
    items: [
      { key: 'merge-slow', href: '/merge',
        q: { pl: 'Scalanie wielu plików działa wolno?', en: 'Merging many files is slow?' , de: 'Das Zusammenführen vieler Dateien ist langsam?', es: '¿Combinar muchos archivos es lento?', pt: 'Unir muitos ficheiros é lento?', no: 'Er det tregt å slå sammen mange filer?', sv: 'Går det långsamt att slå ihop många filer?', fr: 'La fusion de nombreux fichiers est lente ?', ar: 'دمج ملفات متعددة بطيء؟', fa: 'ادغام چندین فایل کند است؟', tr: 'Çok sayıda dosyayı birleştirmek yavaş mı?', hi: 'क्या कई फ़ाइलों को मर्ज करना धीमा है?', is: 'Er sameining margra skráa hæg?', it: 'Unire molti file è lento?', ja: '多数のファイルの結合が遅いですか？', zh: '合并多个文件很慢？'},
        a: { pl: 'Scalanie kilkudziesięciu plików lub plików z wieloma stronami może chwilę potrwać — wszystko dzieje się lokalnie w przeglądarce. Czas zależy od mocy Twojego procesora i ilości pamięci RAM. Dla bardzo dużych plików (ponad 100 stron) zalecamy przetwarzanie w partiach.', en: 'Merging dozens of files or files with many pages may take a moment — everything runs locally in your browser. Time depends on your CPU power and RAM. For very large files (over 100 pages), we recommend processing in batches.' , de: 'Das Zusammenführen von Dutzenden Dateien oder Dateien mit vielen Seiten kann einen Moment dauern – alles läuft lokal in Ihrem Browser. Die Dauer hängt von der Leistung Ihrer CPU und dem Arbeitsspeicher ab. Bei sehr großen Dateien (über 100 Seiten) empfehlen wir die Verarbeitung in Stapeln.', es: 'Combinar decenas de archivos o archivos con muchas páginas puede llevar un momento: todo se ejecuta localmente en su navegador. El tiempo depende de la potencia de su CPU y de la memoria RAM. Para archivos muy grandes (más de 100 páginas), recomendamos procesarlos por lotes.', pt: 'Unir dezenas de ficheiros ou ficheiros com muitas páginas pode demorar um pouco — tudo é processado localmente no seu navegador. O tempo depende da potência do CPU e da memória RAM. Para ficheiros muito grandes (mais de 100 páginas), recomendamos processar em lotes.', no: 'Å slå sammen dusinvis av filer eller filer med mange sider kan ta et øyeblikk — alt kjøres lokalt i nettleseren din. Tiden avhenger av CPU-kraften og RAM-minnet ditt. For svært store filer (over 100 sider) anbefaler vi å behandle i grupper.', sv: 'Att slå ihop flera dussin filer eller filer med många sidor kan ta en stund — allt körs lokalt i din webbläsare. Tiden beror på din CPU-kraft och ditt RAM-minne. För mycket stora filer (över 100 sidor) rekommenderar vi att bearbeta i omgångar.', fr: 'La fusion de plusieurs dizaines de fichiers ou de fichiers comportant de nombreuses pages peut prendre un moment — tout s\'exécute localement dans votre navigateur. La durée dépend de la puissance de votre processeur et de votre RAM. Pour les très gros fichiers (plus de 100 pages), nous recommandons de traiter par lots.', ar: 'قد يستغرق دمج عشرات الملفات أو الملفات ذات الصفحات العديدة بعض الوقت — كل شيء يعمل محليًا في متصفحك. يعتمد الوقت على قوة المعالج (CPU) وذاكرة الوصول العشوائي (RAM). بالنسبة للملفات الكبيرة جدًا (أكثر من 100 صفحة)، نوصي بالمعالجة على دفعات.', fa: 'ادغام ده‌ها فایل یا فایل‌هایی با صفحات زیاد ممکن است کمی طول بکشد — همه چیز به صورت محلی در مرورگر شما اجرا می‌شود. زمان به قدرت CPU و RAM شما بستگی دارد. برای فایل‌های خیلی بزرگ (بیش از 100 صفحه)، پردازش به صورت دسته‌ای را توصیه می‌کنیم.', tr: 'Onlarca dosyayı veya çok sayfalı dosyaları birleştirmek biraz zaman alabilir — her şey tarayıcınızda yerel olarak çalışır. Süre, CPU gücünüze ve RAM\'inize bağlıdır. Çok büyük dosyalar için (100 sayfadan fazla) dosyaları gruplar halinde işlemenizi öneririz.', hi: 'कई दर्जन फ़ाइलों या कई पृष्ठों वाली फ़ाइलों को मर्ज करने में कुछ समय लग सकता है - सब कुछ आपके ब्राउज़र में स्थानीय रूप से चलता है। समय आपके CPU की शक्ति और RAM पर निर्भर करता है। बहुत बड़ी फ़ाइलों (100 से अधिक पृष्ठों) के लिए, हम बैचों में प्रक्रिया करने की सलाह देते हैं।', is: 'Sameining á tugum skráa eða skráa með mörgum síðum getur tekið smá stund — allt keyrir staðbundið í vafranum þínum. Tíminn fer eftir styrk örgjörvans og vinnsluminni. Fyrir mjög stórar skrár (yfir 100 síður) mælum við með vinnslu í hlutum.', it: 'Unire decine di file o file con molte pagine può richiedere qualche istante: tutto viene elaborato localmente nel tuo browser. Il tempo dipende dalla potenza della CPU e dalla RAM. Per file molto grandi (oltre 100 pagine), consigliamo di elaborare in lotti.', ja: '数十のファイルやページ数の多いファイルの結合には時間がかかる場合があります。すべてブラウザ内でローカルに処理されます。処理時間はCPUの性能とRAMの容量によって異なります。非常に大きなファイル（100ページ超）の場合は、バッチ単位で処理することをお勧めします。', zh: '合并几十个文件或页面较多的文件可能需要一些时间——所有操作都在您的浏览器中本地运行。耗时取决于您的CPU性能和内存。对于非常大的文件（超过100页），我们建议分批处理。'},
      },
      { key: 'split-wrong', href: '/split',
        q: { pl: 'Dzielenie nie wyodrębnia poprawnych stron?', en: 'Split is not extracting the right pages?' , de: 'Das Teilen extrahiert nicht die richtigen Seiten?', es: '¿Dividir no extrae las páginas correctas?', pt: 'A ferramenta Dividir não extrai as páginas corretas?', no: 'Trekker ikke delingen ut de riktige sidene?', sv: 'Extraherar delningen inte rätt sidor?', fr: 'La division n\'extrait pas les bonnes pages ?', ar: 'لا يستخرج التقسيم الصفحات الصحيحة؟', fa: 'تقسیم صفحات صحیح را استخراج نمی‌کند؟', tr: 'Bölme işlemi doğru sayfaları çıkarmıyor mu?', hi: 'क्या विभाजन सही पृष्ठ नहीं निकाल रहा है?', is: 'Er skiptingin ekki að draga út réttar síður?', it: 'La divisione non estrae le pagine corrette?', ja: '分割で正しいページが抽出されませんか？', zh: '分割没有提取正确的页面？'},
        a: {
          ar: 'تحقق من طريقة كتابة النطاقات. أمثلة: «1-5» (الصفحات من 1 إلى 5 في ملف واحد)، و«1,3,5» (ثلاثة ملفات في كل منها صفحة واحدة)، و«1-5,8,10-15» (ثلاثة ملفات). تُرقَّم الصفحات بدءًا من 1. يحفظ «صفحة بصفحة» كل صفحة منفصلة؛ ولوضع الصفحات المختارة في ملف واحد استخدم «تقسيم حسب التحديد».',
          de: 'Prüfen Sie die Schreibweise der Bereiche. Beispiele: „1-5“ (Seiten 1 bis 5 in einer Datei), „1,3,5“ (drei Dateien mit je einer Seite), „1-5,8,10-15“ (drei Dateien). Die Seiten werden ab 1 gezählt. „Seite für Seite“ speichert jede Seite einzeln; um gewählte Seiten in eine Datei zu legen, nutzen Sie „Nach Auswahl teilen“.',
          en: 'Check how the ranges are written. Examples: “1-5” (pages 1 to 5 in one file), “1,3,5” (three files with one page each), “1-5,8,10-15” (three files). Pages are numbered from 1. “Page by page” saves every page separately; to put chosen pages into one file, use “Split by selection”.',
          es: 'Comprueba cómo están escritos los rangos. Ejemplos: «1-5» (páginas 1 a 5 en un archivo), «1,3,5» (tres archivos de una página cada uno), «1-5,8,10-15» (tres archivos). Las páginas se numeran desde 1. «Página por página» guarda cada página por separado; para juntar páginas elegidas en un archivo, usa «Dividir por selección».',
          fa: 'شیوهٔ نوشتن بازه‌ها را بررسی کنید. نمونه‌ها: «1-5» (صفحه‌های ۱ تا ۵ در یک فایل)، «1,3,5» (سه فایل هر کدام با یک صفحه)، «1-5,8,10-15» (سه فایل). شمارهٔ صفحه‌ها از ۱ شروع می‌شود. «صفحه به صفحه» هر صفحه را جداگانه ذخیره می‌کند؛ برای قرار دادن صفحه‌های انتخابی در یک فایل از «تقسیم بر اساس انتخاب» استفاده کنید.',
          fr: 'Vérifiez l’écriture des plages. Exemples : « 1-5 » (pages 1 à 5 dans un fichier), « 1,3,5 » (trois fichiers d’une page chacun), « 1-5,8,10-15 » (trois fichiers). Les pages sont numérotées à partir de 1. « Page par page » enregistre chaque page séparément ; pour réunir des pages choisies dans un seul fichier, utilisez « Fractionner par sélection ».',
          hi: 'जाँचें कि दायरे कैसे लिखे गए हैं। उदाहरण: “1-5” (एक फ़ाइल में पृष्ठ 1 से 5), “1,3,5” (तीन फ़ाइलें, हर एक में एक पृष्ठ), “1-5,8,10-15” (तीन फ़ाइलें)। पृष्ठ 1 से गिने जाते हैं। “पृष्ठ दर पृष्ठ” हर पृष्ठ को अलग सहेजता है; चुने गए पृष्ठों को एक फ़ाइल में रखने के लिए “चयन के अनुसार विभाजित करें” का उपयोग करें।',
          is: 'Athugaðu hvernig bilin eru skrifuð. Dæmi: „1-5“ (síður 1 til 5 í einni skrá), „1,3,5“ (þrjár skrár með einni síðu hver), „1-5,8,10-15“ (þrjár skrár). Síður eru númeraðar frá 1. „Síðu fyrir síðu“ vistar hverja síðu sér; til að setja valdar síður í eina skrá notarðu „Skipta eftir vali“.',
          it: 'Controlla come sono scritti gli intervalli. Esempi: «1-5» (pagine da 1 a 5 in un file), «1,3,5» (tre file con una pagina ciascuno), «1-5,8,10-15» (tre file). Le pagine sono numerate da 1. «Pagina per pagina» salva ogni pagina separatamente; per mettere le pagine scelte in un unico file usa «Dividi per selezione».',
          ja: '範囲の書き方を確認してください。例：「1-5」（1〜5 ページを 1 つのファイルに）、「1,3,5」（1 ページずつの 3 ファイル）、「1-5,8,10-15」（3 ファイル）。ページ番号は 1 から始まります。「ページごとに」は各ページを個別に保存します。選んだページを 1 つのファイルにまとめるには「選択で分割」を使ってください。',
          no: 'Sjekk hvordan områdene er skrevet. Eksempler: «1-5» (sidene 1 til 5 i én fil), «1,3,5» (tre filer med én side hver), «1-5,8,10-15» (tre filer). Sidene nummereres fra 1. «Side for side» lagrer hver side for seg; for å legge valgte sider i én fil bruker du «Del etter valg».',
          pl: 'Sprawdź zapis zakresów. Przykłady: „1-5” (strony od 1 do 5 w jednym pliku), „1,3,5” (trzy pliki, w każdym jedna strona), „1-5,8,10-15” (trzy pliki). Strony są numerowane od 1. Tryb „Strona po stronie” zapisuje każdą stronę osobno; aby wybrane strony trafiły do jednego pliku, użyj trybu „Podziel wg zaznaczenia”.',
          pt: 'Verifique como estão escritos os intervalos. Exemplos: «1-5» (páginas 1 a 5 num ficheiro), «1,3,5» (três ficheiros com uma página cada), «1-5,8,10-15» (três ficheiros). As páginas são numeradas a partir de 1. «Página a página» guarda cada página em separado; para juntar páginas escolhidas num só ficheiro, use «Dividir por seleção».',
          sv: 'Kontrollera hur intervallen är skrivna. Exempel: ”1-5” (sidorna 1 till 5 i en fil), ”1,3,5” (tre filer med en sida var), ”1-5,8,10-15” (tre filer). Sidorna numreras från 1. ”Sida för sida” sparar varje sida för sig; för att lägga valda sidor i en fil använder du ”Dela efter markering”.',
          tr: 'Aralıkların nasıl yazıldığını kontrol edin. Örnekler: “1-5” (tek dosyada 1’den 5’e kadar sayfalar), “1,3,5” (her biri tek sayfalık üç dosya), “1-5,8,10-15” (üç dosya). Sayfalar 1’den başlayarak numaralandırılır. “Sayfa sayfa” her sayfayı ayrı kaydeder; seçtiğiniz sayfaları tek dosyada toplamak için “Seçime göre böl” modunu kullanın.',
          zh: '请检查范围的写法。例如：“1-5”（第 1 到 5 页放在一个文件中），“1,3,5”（三个文件，每个一页），“1-5,8,10-15”（三个文件）。页码从 1 开始。“逐页拆分”会把每页单独保存；要把选中的页面放进一个文件，请使用“按选择拆分”。',
        },
      },
      { key: 'compress-nochange', href: '/compress',
        q: { pl: 'Kompresja nie zmniejsza rozmiaru pliku?', en: 'Compression doesn\'t reduce file size?' , de: 'Die Komprimierung verkleinert die Datei nicht?', es: '¿La compresión no reduce el tamaño del archivo?', pt: 'A compressão não reduz o tamanho do ficheiro?', no: 'Reduserer ikke komprimeringen filstørrelsen?', sv: 'Minskar inte komprimeringen filstorleken?', fr: 'La compression ne réduit pas la taille du fichier ?', ar: 'لا يقلل الضغط من حجم الملف؟', fa: 'فشرده‌سازی حجم فایل را کاهش نمی‌دهد؟', tr: 'Sıkıştırma dosya boyutunu küçültmüyor mu?', hi: 'क्या संपीड़न फ़ाइल का आकार कम नहीं करता है?', is: 'Minnkar þjöppunin ekki stærð skráarinnar?', it: 'La compressione non riduce le dimensioni del file?', ja: '圧縮してもファイルサイズが小さくなりませんか？', zh: '压缩没有减小文件大小？'},
        a: { pl: 'Jeśli plik PDF zawiera głównie tekst (a nie obrazy), kompresja może nie przynieść znaczącej różnicy — tekst już jest mocno skompresowany. PDF z obrazami skompresuje się lepiej. Spróbuj wybrać wyższy poziom kompresji. Jeśli plik jest już zoptymalizowany, dalsza kompresja może być niemożliwa.', en: 'If the PDF contains mostly text (not images), compression may not make a significant difference — text is already highly compressed. Image-based PDFs will compress better. Try a higher compression level. If the file is already optimized, further compression may not be possible.' , de: 'Wenn das PDF hauptsächlich Text enthält (keine Bilder), kann die Komprimierung keinen nennenswerten Unterschied bewirken – Text ist bereits stark komprimiert. Bildbasierte PDFs lassen sich besser komprimieren. Versuchen Sie eine höhere Komprimierungsstufe. Wenn die Datei bereits optimiert ist, ist eine weitere Komprimierung möglicherweise nicht möglich.', es: 'Si el PDF contiene principalmente texto (no imágenes), la compresión puede no suponer una diferencia significativa: el texto ya está muy comprimido. Los PDF basados en imágenes se comprimen mejor. Pruebe un nivel de compresión más alto. Si el archivo ya está optimizado, puede que no sea posible comprimirlo más.', pt: 'Se o PDF contiver sobretudo texto (e não imagens), a compressão pode não fazer uma diferença significativa — o texto já está altamente comprimido. Os PDF baseados em imagens comprimem melhor. Experimente um nível de compressão mais elevado. Se o ficheiro já estiver otimizado, pode não ser possível comprimir mais.', no: 'Hvis PDF-en hovedsakelig inneholder tekst (ikke bilder), kan komprimeringen kanskje ikke utgjøre en stor forskjell — tekst er allerede svært komprimert. PDF-er basert på bilder komprimeres bedre. Prøv et høyere komprimeringsnivå. Hvis filen allerede er optimalisert, kan det hende at ytterligere komprimering ikke er mulig.', sv: 'Om PDF-filen huvudsakligen innehåller text (inte bilder) kanske komprimeringen inte gör någon större skillnad — text är redan mycket komprimerad. PDF-filer som är baserade på bilder komprimeras bättre. Prova en högre komprimeringsnivå. Om filen redan är optimerad kanske ytterligare komprimering inte är möjlig.', fr: 'Si le PDF contient principalement du texte (pas d\'images), la compression peut ne pas faire une grande différence — le texte est déjà fortement compressé. Les PDF à base d\'images se compressent mieux. Essayez un niveau de compression plus élevé. Si le fichier est déjà optimisé, une compression supplémentaire n\'est peut-être pas possible.', ar: 'إذا كان ملف PDF يحتوي بشكل أساسي على نص (وليس صورًا)، فقد لا يحدث الضغط فرقًا كبيرًا — النص مضغوط بالفعل بدرجة عالية. تُضغط ملفات PDF المستندة إلى الصور بشكل أفضل. جرّب مستوى ضغط أعلى. إذا كان الملف محسّنًا بالفعل، فقد لا يكون من الممكن ضغطه أكثر.', fa: 'اگر PDF عمدتاً حاوی متن باشد (نه تصویر)، فشرده‌سازی ممکن است تفاوت قابل توجهی ایجاد نکند — متن از قبل به شدت فشرده شده است. PDF‌های مبتنی بر تصویر بهتر فشرده می‌شوند. سطح فشرده‌سازی بالاتری را امتحان کنید. اگر فایل از قبل بهینه شده باشد، فشرده‌سازی بیشتر ممکن است ممکن نباشد.', tr: 'PDF çoğunlukla metin içeriyorsa (görsel değil), sıkıştırma önemli bir fark yaratmayabilir — metin zaten yüksek oranda sıkıştırılmıştır. Görsel tabanlı PDF\'ler daha iyi sıkıştırılır. Daha yüksek bir sıkıştırma düzeyi deneyin. Dosya zaten optimize edilmişse daha fazla sıkıştırma mümkün olmayabilir.', hi: 'यदि PDF में अधिकतर टेक्स्ट है (छवियाँ नहीं), तो संपीड़न से महत्वपूर्ण अंतर नहीं पड़ सकता है - टेक्स्ट पहले से ही अत्यधिक संपीड़ित होता है। छवि-आधारित PDF बेहतर संपीड़ित होंगी। उच्च संपीड़न स्तर आज़माएँ। यदि फ़ाइल पहले से अनुकूलित है, तो आगे संपीड़न संभव नहीं हो सकता है।', is: 'Ef PDF-ið inniheldur aðallega texta (ekki myndir) getur þjöppunin haft lítil áhrif — texti er nú þegar mjög þjappaður. PDF-skjöl sem byggjast á myndum þjappast betur. Prófaðu hærra þjöppunarstig. Ef skráin er nú þegar fínstillt gæti frekari þjöppun ekki verið möguleg.', it: 'Se il PDF contiene principalmente testo (non immagini), la compressione potrebbe non produrre una differenza significativa: il testo è già altamente compresso. I PDF basati su immagini si comprimono meglio. Prova un livello di compressione più alto. Se il file è già ottimizzato, un\'ulteriore compressione potrebbe non essere possibile.', ja: 'PDFの内容がほとんどテキスト（画像ではない）の場合、圧縮しても大きな違いはないかもしれません。テキストはすでに高度に圧縮されているためです。画像ベースのPDFの方が圧縮効果は高くなります。より高い圧縮レベルを試してください。ファイルがすでに最適化されている場合は、それ以上圧縮できない可能性があります。', zh: '如果PDF主要包含文本（而非图像），压缩可能不会有显著效果——文本已经被高度压缩。基于图像的PDF压缩效果更好。请尝试更高的压缩级别。如果文件已经过优化，可能无法进一步压缩。'},
      },
      { key: 'crop-wrong', href: '/crop-pdf',
        q: { pl: 'Przycięcie usuwa złe fragmenty strony?', en: 'Cropping removes the wrong parts of the page?' , de: 'Beim Zuschneiden werden die falschen Teile der Seite entfernt?', es: '¿El recorte elimina partes incorrectas de la página?', pt: 'O recorte remove as partes erradas da página?', no: 'Fjerner beskjæringen feil deler av siden?', sv: 'Tar beskäringen bort fel delar av sidan?', fr: 'Le rognage supprime de mauvaises parties de la page ?', ar: 'يزيل القص أجزاء خاطئة من الصفحة؟', fa: 'برش بخش‌های اشتباه صفحه را حذف می‌کند؟', tr: 'Kırpma, sayfanın yanlış bölümlerini mi kaldırıyor?', hi: 'क्या क्रॉप करना पृष्ठ के गलत भागों को हटा देता है?', is: 'Fjarlægir klippingin rangar hlutar síðunnar?', it: 'Il ritaglio rimuove le parti sbagliate della pagina?', ja: 'トリミングでページの間違った部分が削除されますか？', zh: '裁剪删除了页面中错误的部分？'},
        a: {
          ar: 'تُدخل الهوامش بالوحدة التي تختارها (نقاط أو مليمترات أو بوصات)، وافتراضيًا لا يُقص شيء. لصفحة A4 (595 × 842 pt) جرّب 30 pt يسارًا ويمينًا و40 pt أعلى وأسفل. لا توجد معاينة، لذا ابدأ بقيم صغيرة وتحقق من النتيجة. لاقتصاص بعض الصفحات فقط، حددها في الصور المصغرة؛ ومن دون تحديد تُقتص جميع الصفحات.',
          de: 'Die Ränder geben Sie in der gewählten Einheit ein (Punkt, Millimeter oder Zoll); standardmäßig wird nichts abgeschnitten. Für eine A4-Seite (595 × 842 pt) versuchen Sie 30 pt links und rechts sowie 40 pt oben und unten. Eine Vorschau gibt es nicht, beginnen Sie also mit kleinen Werten und prüfen Sie das Ergebnis. Um nur einige Seiten zuzuschneiden, markieren Sie sie in den Miniaturen; ohne Auswahl werden alle Seiten zugeschnitten.',
          en: 'Margins are entered in the unit you choose (points, millimetres or inches); by default nothing is cut. For an A4 page (595 × 842 pt) try 30 pt on the left and right and 40 pt at the top and bottom. There is no preview, so start with small values and check the result. To crop only some pages, tick them on the thumbnails; with no selection every page is cropped.',
          es: 'Los márgenes se indican en la unidad que elijas (puntos, milímetros o pulgadas); por defecto no se recorta nada. Para una página A4 (595 × 842 pt) prueba 30 pt a izquierda y derecha y 40 pt arriba y abajo. No hay vista previa, así que empieza con valores pequeños y comprueba el resultado. Para recortar solo algunas páginas, márcalas en las miniaturas; sin selección se recortan todas.',
          fa: 'حاشیه‌ها را با واحدی که انتخاب می‌کنید (پوینت، میلی‌متر یا اینچ) وارد می‌کنید؛ به‌طور پیش‌فرض چیزی بریده نمی‌شود. برای صفحهٔ A4 ‏(595 × 842 pt) ‏۳۰ pt از چپ و راست و ۴۰ pt از بالا و پایین را امتحان کنید. پیش‌نمایشی وجود ندارد، پس با مقادیر کوچک شروع کنید و نتیجه را بررسی کنید. برای برش فقط برخی صفحه‌ها، آن‌ها را در تصاویر کوچک علامت بزنید؛ بدون انتخاب همهٔ صفحه‌ها بریده می‌شوند.',
          fr: 'Les marges se saisissent dans l’unité choisie (points, millimètres ou pouces) ; par défaut, rien n’est coupé. Pour une page A4 (595 × 842 pt), essayez 30 pt à gauche et à droite et 40 pt en haut et en bas. Il n’y a pas d’aperçu : commencez par de petites valeurs et vérifiez le résultat. Pour ne recadrer que certaines pages, cochez-les sur les miniatures ; sans sélection, toutes les pages sont recadrées.',
          hi: 'हाशिये आपकी चुनी इकाई (पॉइंट, मिलीमीटर या इंच) में दर्ज होते हैं; डिफ़ॉल्ट रूप से कुछ नहीं काटा जाता। A4 पृष्ठ (595 × 842 pt) के लिए बाएँ और दाएँ 30 pt तथा ऊपर और नीचे 40 pt आज़माएँ। पूर्वावलोकन नहीं है, इसलिए छोटे मानों से शुरू करें और परिणाम जाँचें। केवल कुछ पृष्ठ क्रॉप करने हों तो थंबनेल पर उन्हें चुनें; चयन न होने पर सभी पृष्ठ क्रॉप होते हैं।',
          is: 'Spássíur eru slegnar inn í einingunni sem þú velur (punktum, millimetrum eða tommum); sjálfgefið er ekkert skorið. Fyrir A4-síðu (595 × 842 pt) skaltu prófa 30 pt vinstra og hægra megin og 40 pt efst og neðst. Engin forskoðun er í boði, svo byrjaðu á litlum gildum og athugaðu útkomuna. Til að klippa aðeins sumar síður merkirðu þær á smámyndunum; án vals eru allar síður klipptar.',
          it: 'I margini si inseriscono nell’unità scelta (punti, millimetri o pollici); per impostazione predefinita non viene tagliato nulla. Per una pagina A4 (595 × 842 pt) prova 30 pt a sinistra e a destra e 40 pt in alto e in basso. Non c’è anteprima, quindi parti da valori piccoli e controlla il risultato. Per ritagliare solo alcune pagine, selezionale nelle miniature; senza selezione vengono ritagliate tutte.',
          ja: '余白は選んだ単位（ポイント、ミリ、インチ）で入力します。初期値では何も切り取りません。A4 ページ（595 × 842 pt）なら、左右 30 pt、上下 40 pt から試してください。プレビューはないため、小さな値から始めて結果を確認しましょう。一部のページだけをトリミングするには、サムネイルでそのページにチェックを入れます。選択しない場合はすべてのページが対象になります。',
          no: 'Margene angis i enheten du velger (punkter, millimeter eller tommer); som standard fjernes ingenting. For en A4-side (595 × 842 pt) kan du prøve 30 pt til venstre og høyre og 40 pt øverst og nederst. Det finnes ingen forhåndsvisning, så start med små verdier og sjekk resultatet. For å beskjære bare noen sider merker du dem blant miniatyrene; uten merking beskjæres alle sider.',
          pl: 'Marginesy wpisujesz w wybranej jednostce (punkty, milimetry albo cale); domyślnie nic nie jest odcinane. Dla strony A4 (595 × 842 pt) spróbuj 30 pt z lewej i prawej oraz 40 pt u góry i u dołu. Narzędzie nie pokazuje podglądu, więc zacznij od małych wartości i sprawdź wynik. Aby przyciąć tylko niektóre strony, zaznacz je na miniaturach; bez zaznaczenia przycinane są wszystkie.',
          pt: 'As margens são indicadas na unidade que escolher (pontos, milímetros ou polegadas); por predefinição nada é cortado. Para uma página A4 (595 × 842 pt) experimente 30 pt à esquerda e à direita e 40 pt em cima e em baixo. Não há pré-visualização, por isso comece com valores pequenos e verifique o resultado. Para recortar só algumas páginas, marque-as nas miniaturas; sem seleção, todas são recortadas.',
          sv: 'Marginalerna anges i den enhet du väljer (punkter, millimeter eller tum); som standard tas inget bort. För en A4-sida (595 × 842 pt) kan du prova 30 pt till vänster och höger och 40 pt upptill och nedtill. Det finns ingen förhandsvisning, så börja med små värden och kontrollera resultatet. För att bara beskära vissa sidor markerar du dem bland miniatyrerna; utan markering beskärs alla sidor.',
          tr: 'Kenar boşlukları seçtiğiniz birimde (nokta, milimetre veya inç) girilir; varsayılan olarak hiçbir şey kesilmez. A4 bir sayfa (595 × 842 pt) için solda ve sağda 30 pt, üstte ve altta 40 pt deneyin. Önizleme yoktur; küçük değerlerle başlayıp sonucu kontrol edin. Yalnızca bazı sayfaları kırpmak için onları küçük resimlerde işaretleyin; seçim yoksa tüm sayfalar kırpılır.',
          zh: '边距使用你选择的单位输入（点、毫米或英寸）；默认不裁剪任何内容。对于 A4 页面（595 × 842 pt），可以先试左右各 30 pt、上下各 40 pt。该工具没有预览，所以请从较小的数值开始并检查结果。如果只想裁剪部分页面，请在缩略图上勾选；不选择时会裁剪所有页面。',
        },
      },
      { key: 'watermark-notvisible', href: '/watermark-pdf',
        q: { pl: 'Znak wodny jest niewidoczny lub zbyt duży?', en: 'Watermark is invisible or too large?' , de: 'Das Wasserzeichen ist unsichtbar oder zu groß?', es: '¿La marca de agua es invisible o demasiado grande?', pt: 'A marca de água está invisível ou é demasiado grande?', no: 'Er vannmerket usynlig eller for stort?', sv: 'Är vattenstämpeln osynlig eller för stor?', fr: 'Le filigrane est invisible ou trop grand ?', ar: 'العلامة المائية غير مرئية أو كبيرة جدًا؟', fa: 'واترمارک نامرئی است یا خیلی بزرگ است؟', tr: 'Filigran görünmüyor veya çok mu büyük?', hi: 'क्या वॉटरमार्क अदृश्य है या बहुत बड़ा है?', is: 'Er vatnsmerkið ósýnilegt eða of stórt?', it: 'La filigrana è invisibile o troppo grande?', ja: '透かしが見えないか、大きすぎますか？', zh: '水印不可见或太大？'},
        a: {
          ar: 'درجة العتامة الافتراضية 50%: القيمة الأعلى تجعل العلامة المائية أوضح، والأقل تجعلها أبهت. إذا كان النص كبيرًا جدًا فقلّل حجم الخط، وفي الصفحات الداكنة اختر اللون الأبيض. تكون العلامة المائية مائلة دائمًا، ويمكنك وضعها أعلى الصفحة أو وسطها أو أسفلها.',
          de: 'Die Standarddeckkraft beträgt 50 %: Ein höherer Wert macht das Wasserzeichen deutlicher, ein niedrigerer blasser. Ist der Text zu groß, verringern Sie die Schriftgröße; auf dunklen Seiten wählen Sie Weiß. Das Wasserzeichen verläuft immer schräg und lässt sich oben, in der Mitte oder unten auf der Seite platzieren.',
          en: 'The default opacity is 50%: a higher value makes the watermark more visible, a lower one fainter. If the text is too large, reduce the font size; on dark pages choose white. The watermark always runs diagonally, and you can place it at the top, centre or bottom of the page.',
          es: 'La opacidad predeterminada es del 50 %: un valor más alto hace la marca de agua más visible y uno más bajo, más tenue. Si el texto es demasiado grande, reduce el tamaño de letra; en páginas oscuras elige el blanco. La marca de agua siempre va en diagonal y puedes colocarla arriba, en el centro o abajo de la página.',
          fa: 'میزان کدری پیش‌فرض ۵۰٪ است: مقدار بیشتر واترمارک را پررنگ‌تر و مقدار کمتر کم‌رنگ‌تر می‌کند. اگر متن خیلی بزرگ است، اندازهٔ قلم را کم کنید؛ در صفحه‌های تیره رنگ سفید را انتخاب کنید. واترمارک همیشه مورب است و می‌توانید آن را بالا، وسط یا پایین صفحه بگذارید.',
          fr: 'L’opacité par défaut est de 50 % : une valeur plus élevée rend le filigrane plus visible, une valeur plus faible plus pâle. Si le texte est trop grand, réduisez la taille de police ; sur les pages sombres, choisissez le blanc. Le filigrane est toujours en diagonale et peut être placé en haut, au centre ou en bas de la page.',
          hi: 'डिफ़ॉल्ट अपारदर्शिता 50% है: अधिक मान वॉटरमार्क को ज़्यादा स्पष्ट बनाता है, कम मान हल्का। टेक्स्ट बहुत बड़ा हो तो फ़ॉन्ट आकार घटाएँ; गहरे पृष्ठों पर सफ़ेद रंग चुनें। वॉटरमार्क हमेशा तिरछा रहता है और आप उसे पृष्ठ के ऊपर, बीच में या नीचे रख सकते हैं।',
          is: 'Sjálfgefið ógegnsæi er 50%: hærra gildi gerir vatnsmerkið sýnilegra og lægra gildi daufara. Ef textinn er of stór skaltu minnka leturstærðina; á dökkum síðum velurðu hvítt. Vatnsmerkið liggur alltaf á ská og þú getur sett það efst, á miðja síðu eða neðst.',
          it: 'L’opacità predefinita è del 50%: un valore più alto rende la filigrana più visibile, uno più basso più tenue. Se il testo è troppo grande, riduci la dimensione del carattere; sulle pagine scure scegli il bianco. La filigrana è sempre in diagonale e puoi metterla in alto, al centro o in basso nella pagina.',
          ja: '不透明度の初期値は 50% です。値を上げると透かしがはっきりし、下げると薄くなります。文字が大きすぎる場合は文字サイズを小さくし、暗いページでは白を選んでください。透かしは常に斜めに入り、ページの上・中央・下に配置できます。',
          no: 'Standard opasitet er 50 %: en høyere verdi gjør vannmerket tydeligere, en lavere blekere. Er teksten for stor, reduserer du skriftstørrelsen; på mørke sider velger du hvitt. Vannmerket går alltid diagonalt og kan plasseres øverst, i midten eller nederst på siden.',
          pl: 'Domyślne krycie to 50%: wyższa wartość sprawia, że znak wodny jest lepiej widoczny, niższa — że jest bledszy. Jeśli tekst jest za duży, zmniejsz rozmiar czcionki; na ciemnych stronach wybierz kolor biały. Znak wodny zawsze biegnie ukośnie, a możesz go umieścić u góry, na środku lub u dołu strony.',
          pt: 'A opacidade predefinida é de 50%: um valor mais alto torna a marca de água mais visível e um mais baixo, mais ténue. Se o texto for grande demais, reduza o tamanho da letra; em páginas escuras escolha o branco. A marca de água vai sempre na diagonal e pode colocá-la em cima, ao centro ou em baixo da página.',
          sv: 'Standardopaciteten är 50 %: ett högre värde gör vattenstämpeln tydligare, ett lägre blekare. Om texten är för stor minskar du teckenstorleken; på mörka sidor väljer du vitt. Vattenstämpeln går alltid diagonalt och kan placeras upptill, i mitten eller nedtill på sidan.',
          tr: 'Varsayılan opaklık %50’dir: daha yüksek değer filigranı daha görünür, daha düşük değer daha soluk yapar. Metin çok büyükse yazı boyutunu küçültün; koyu sayfalarda beyazı seçin. Filigran her zaman çaprazdır ve sayfanın üstüne, ortasına veya altına yerleştirilebilir.',
          zh: '不透明度默认为 50%：数值越高水印越明显，越低越淡。如果文字太大，请减小字号；在深色页面上请选择白色。水印始终斜向排列，可以放在页面的顶部、中间或底部。',
        },
      },
      { key: 'redact-notworking', href: '/redact-pdf',
        q: { pl: 'Redakcja nie zakrywa tekstu poprawnie?', en: 'Redaction doesn\'t cover text correctly?' , de: 'Die Schwärzung bedeckt den Text nicht richtig?', es: '¿La redacción no cubre el texto correctamente?', pt: 'A redação não cobre o texto corretamente?', no: 'Dekker ikke sensureringen teksten riktig?', sv: 'Täcker inte svärtningen texten korrekt?', fr: 'Le caviardage ne couvre pas correctement le texte ?', ar: 'التنقيح لا يغطي النص بشكل صحيح؟', fa: 'سیاه‌کردن متن را به درستی پوشش نمی‌دهد؟', tr: 'Sansürleme metni doğru kapatmıyor mu?', hi: 'क्या रेडैक्शन टेक्स्ट को सही ढंग से कवर नहीं करता है?', is: 'Þekur afmörkunin textann ekki rétt?', it: 'L\'oscuramento non copre correttamente il testo?', ja: '黒塗りがテキストを正しく覆いませんか？', zh: '遮蔽没有正确覆盖文本？'},
        a: { pl: 'Redakcja działa poprzez zakrycie wybranego obszaru czarnym prostokątem. Upewnij się, że prostokąt w pełni pokrywa tekst, który chcesz usunąć. Redakcja jest trwała — po zapisaniu nie można cofnąć tej operacji. Zawsze rób kopię oryginalnego pliku przed redakcją.', en: 'Redaction works by covering the selected area with a black rectangle. Make sure the rectangle fully covers the text you want to remove. Redaction is permanent — once saved, this operation cannot be undone. Always keep a copy of the original file before redacting.' , de: 'Die Schwärzung funktioniert, indem der ausgewählte Bereich mit einem schwarzen Rechteck abgedeckt wird. Stellen Sie sicher, dass das Rechteck den Text, den Sie entfernen möchten, vollständig abdeckt. Die Schwärzung ist dauerhaft – nach dem Speichern kann dieser Vorgang nicht rückgängig gemacht werden. Erstellen Sie vor dem Schwärzen immer eine Kopie der Originaldatei.', es: 'La redacción funciona cubriendo el área seleccionada con un rectángulo negro. Asegúrese de que el rectángulo cubra por completo el texto que desea eliminar. La redacción es permanente: una vez guardada, esta operación no se puede deshacer. Haga siempre una copia del archivo original antes de redactar.', pt: 'A redação funciona cobrindo a área selecionada com um retângulo preto. Certifique-se de que o retângulo cobre totalmente o texto que pretende remover. A redação é permanente — uma vez guardada, esta operação não pode ser anulada. Guarde sempre uma cópia do ficheiro original antes de redigir.', no: 'Sensurering fungerer ved å dekke det valgte området med en svart rektangel. Kontroller at rektangelet dekker teksten du vil fjerne, fullstendig. Sensurering er permanent — når du har lagret, kan denne operasjonen ikke angres. Ta alltid en kopi av originalfilen før du sensurerer.', sv: 'Svärtning fungerar genom att täcka det valda området med en svart rektangel. Kontrollera att rektangeln helt täcker texten du vill ta bort. Svärtning är permanent — när du har sparat kan den här åtgärden inte ångras. Ta alltid en kopia av originalfilen innan du svärtar.', fr: 'Le caviardage fonctionne en recouvrant la zone sélectionnée d\'un rectangle noir. Assurez-vous que le rectangle couvre entièrement le texte à supprimer. Le caviardage est définitif — une fois enregistré, cette opération ne peut pas être annulée. Conservez toujours une copie du fichier original avant de caviarder.', ar: 'يعمل التنقيح عن طريق تغطية المنطقة المحددة بمستطيل أسود. تأكد من أن المستطيل يغطي النص الذي تريد إزالته بالكامل. التنقيح دائم — بمجرد الحفظ، لا يمكن التراجع عن هذه العملية. احتفظ دائمًا بنسخة من الملف الأصلي قبل التنقيح.', fa: 'سیاه‌کردن با پوشاندن ناحیه انتخاب‌شده با یک مستطیل سیاه کار می‌کند. مطمئن شوید مستطیل متنی را که می‌خواهید حذف کنید کاملاً می‌پوشاند. سیاه‌کردن دائمی است — پس از ذخیره، این عملیات قابل بازگشت نیست. همیشه قبل از سیاه‌کردن، یک کپی از فایل اصلی نگه دارید.', tr: 'Sansürleme, seçilen alanı siyah bir dikdörtgenle kapatarak çalışır. Dikdörtgenin kaldırmak istediğiniz metni tamamen kapladığından emin olun. Sansürleme kalıcıdır — kaydedildikten sonra bu işlem geri alınamaz. Sansürlemeden önce her zaman orijinal dosyanın bir kopyasını saklayın.', hi: 'रेडैक्शन चयनित क्षेत्र को एक काले आयत से ढककर काम करता है। सुनिश्चित करें कि आयत उस टेक्स्ट को पूरी तरह से कवर करता है जिसे आप हटाना चाहते हैं। रेडैक्शन स्थायी है - सहेजने के बाद इस ऑपरेशन को पूर्ववत नहीं किया जा सकता। रेडैक्शन से पहले हमेशा मूल फ़ाइल की एक प्रति रखें।', is: 'Afmörkun virkar með því að þekja valda svæðið með svörtum rétthyrningi. Gakktu úr skugga um að rétthyrningurinn þeki að fullu textann sem þú vilt fjarlægja. Afmörkun er varanleg — eftir vistun er ekki hægt að afturkalla aðgerðina. Hafðu alltaf afrit af upprunalegu skránni áður en þú afmarkar.', it: 'L\'oscuramento funziona coprendo l\'area selezionata con un rettangolo nero. Assicurati che il rettangolo copra completamente il testo che vuoi rimuovere. L\'oscuramento è permanente: una volta salvato, questa operazione non può essere annullata. Conserva sempre una copia del file originale prima di oscurare.', ja: '黒塗りは、選択した領域を黒い長方形で覆うことで機能します。削除したいテキストを長方形が完全に覆っていることを確認してください。黒塗りは永続的です。保存すると、この操作は元に戻せません。黒塗りを行う前に、必ず元のファイルのコピーを保存しておいてください。', zh: '遮蔽功能通过用黑色矩形覆盖所选区域来工作。请确保矩形完全覆盖您要删除的文本。遮蔽是永久性的——保存后，此操作无法撤销。遮蔽之前请始终保留原始文件的副本。'},
      },
      { key: 'pagenumbers-position', href: '/page-numbers',
        q: { pl: 'Numery stron nakładają się na treść?', en: 'Page numbers overlap with content?' , de: 'Seitenzahlen überlappen den Inhalt?', es: '¿Los números de página se superponen con el contenido?', pt: 'Os números de página sobrepõem-se ao conteúdo?', no: 'Overlapper sidenumrene innholdet?', sv: 'Överlappar sidnumren innehållet?', fr: 'Les numéros de page chevauchent le contenu ?', ar: 'أرقام الصفحات تتداخل مع المحتوى؟', fa: 'شماره صفحه‌ها با محتوا همپوشانی دارند؟', tr: 'Sayfa numaraları içerikle çakışıyor mu?', hi: 'क्या पृष्ठ संख्याएँ सामग्री के साथ ओवरलैप होती हैं?', is: 'Skarast síðunúmerin við efnið?', it: 'I numeri di pagina si sovrappongono al contenuto?', ja: 'ページ番号がコンテンツと重なりますか？', zh: '页码与内容重叠？'},
        a: { pl: 'Jeśli numery stron nachodzą na treść dokumentu, spróbuj zmienić pozycję (góra/dół) lub wyrównanie (lewo/prawo). Możesz też zmienić rozmiar czcionki na mniejszy. Dla dokumentów z małymi marginesami wybierz pozycję "Dół" z wyrównaniem do prawej.', en: 'If page numbers overlap with document content, try changing the position (top/bottom) or alignment (left/right). You can also reduce the font size. For documents with small margins, choose "Bottom" position with right alignment.' , de: 'Wenn Seitenzahlen den Dokumentinhalt überlappen, versuchen Sie, die Position (oben/unten) oder Ausrichtung (links/rechts) zu ändern. Sie können auch die Schriftgröße verkleinern. Wählen Sie bei Dokumenten mit kleinen Rändern die Position „Unten“ mit rechtsbündiger Ausrichtung.', es: 'Si los números de página se superponen con el contenido del documento, pruebe a cambiar la posición (arriba/abajo) o la alineación (izquierda/derecha). También puede reducir el tamaño de la fuente. Para documentos con márgenes pequeños, elija la posición «Abajo» con alineación a la derecha.', pt: 'Se os números de página se sobrepuserem ao conteúdo do documento, experimente alterar a posição (topo/fundo) ou o alinhamento (esquerda/direita). Também pode reduzir o tamanho da fonte. Para documentos com margens pequenas, escolha a posição «Fundo» com alinhamento à direita.', no: 'Hvis sidenumrene overlapper dokumentinnholdet, prøv å endre posisjonen (topp/bunn) eller justeringen (venstre/høyre). Du kan også redusere skriftstørrelsen. For dokumenter med små marger, velg posisjonen «Bunn» med høyrejustering.', sv: 'Om sidnumren överlappar dokumentinnehållet, prova att ändra positionen (topp/botten) eller justeringen (vänster/höger). Du kan också minska teckenstorleken. För dokument med små marginaler, välj positionen ”Botten” med högerjustering.', fr: 'Si les numéros de page chevauchent le contenu du document, essayez de modifier la position (haut/bas) ou l\'alignement (gauche/droite). Vous pouvez également réduire la taille de police. Pour les documents à petites marges, choisissez la position « Bas » avec un alignement à droite.', ar: 'إذا كانت أرقام الصفحات تتداخل مع محتوى المستند، جرّب تغيير الموضع (أعلى/أسفل) أو المحاذاة (يسار/يمين). يمكنك أيضًا تقليل حجم الخط. بالنسبة للمستندات ذات الهوامش الصغيرة، اختر الموضع "أسفل" مع محاذاة إلى اليمين.', fa: 'اگر شماره صفحه‌ها با محتوای سند همپوشانی دارند، موقعیت (بالا/پایین) یا تراز (چپ/راست) را تغییر دهید. همچنین می‌توانید اندازه فونت را کاهش دهید. برای اسناد با حاشیه‌های کوچک، موقعیت "پایین" را با تراز راست انتخاب کنید.', tr: 'Sayfa numaraları belge içeriğiyle çakışıyorsa konumu (üst/alt) veya hizalamayı (sol/sağ) değiştirmeyi deneyin. Ayrıca yazı boyutunu da küçültebilirsiniz. Kenar boşlukları küçük olan belgeler için "Alt" konumunu sağ hizalama ile seçin.', hi: 'यदि पृष्ठ संख्याएँ दस्तावेज़ की सामग्री के साथ ओवरलैप होती हैं, तो स्थिति (ऊपर/नीचे) या संरेखण (बाएँ/दाएँ) बदलने का प्रयास करें। आप फ़ॉन्ट का आकार भी कम कर सकते हैं। छोटे मार्जिन वाले दस्तावेज़ों के लिए, दाएँ संरेखण के साथ "नीचे" स्थिति चुनें।', is: 'Ef síðunúmerin skarast við efni skjalsins skaltu prófa að breyta staðsetningunni (efst/neðst) eða röðuninni (vinstri/hægri). Þú getur líka minnkað leturstærðina. Fyrir skjöl með litlum spássíum skaltu velja staðsetninguna "Neðst" með hægri röðun.', it: 'Se i numeri di pagina si sovrappongono al contenuto del documento, prova a cambiare la posizione (in alto/in basso) o l\'allineamento (a sinistra/a destra). Puoi anche ridurre la dimensione del carattere. Per i documenti con margini piccoli, scegli la posizione «In basso» con allineamento a destra.', ja: 'ページ番号がドキュメントのコンテンツと重なる場合は、位置（上/下）や配置（左/右）を変更してみてください。フォントサイズを小さくすることもできます。余白が小さいドキュメントの場合は、右揃えで「下部」の位置を選択してください。', zh: '如果页码与文档内容重叠，请尝试更改位置（顶部/底部）或对齐方式（左/右）。您也可以减小字体大小。对于边距较小的文档，请选择“底部”位置并右对齐。'},
      },
      { key: 'edit-addtext', href: '/edit-pdf',
        q: { pl: 'Dodany tekst nie wygląda tak jak w oryginalnym dokumencie?', en: 'Added text doesn\'t match the original document?' , de: 'Hinzugefügter Text entspricht nicht dem Originaldokument?', es: '¿El texto añadido no coincide con el documento original?', pt: 'O texto adicionado não corresponde ao documento original?', no: 'Samsvarer ikke den tilføyde teksten med originaldokumentet?', sv: 'Matchar inte den tillagda texten originaldokumentet?', fr: 'Le texte ajouté ne correspond pas au document original ?', ar: 'النص المضاف لا يطابق المستند الأصلي؟', fa: 'متن اضافه‌شده با سند اصلی مطابقت ندارد؟', tr: 'Eklenen metin orijinal belgeyle eşleşmiyor mu?', hi: 'क्या जोड़ा गया टेक्स्ट मूल दस्तावेज़ से मेल नहीं खाता है?', is: 'Passar viðbætti textinn ekki við upprunalega skjalið?', it: 'Il testo aggiunto non corrisponde al documento originale?', ja: '追加したテキストが元のドキュメントと一致しませんか？', zh: '添加的文本与原始文档不一致？'},
        a: {
          ar: 'انقر على النص الموجود لتصحيحه. يُكتب النص الجديد بالخط الذي تختاره من قائمة الخطوط الاثني عشر، لذا قد يختلف عن خط المستند الأصلي. يغطي النصَّ القديم مستطيلٌ بلون الخلفية، لكنه يبقى في الملف (يظهر عند النسخ أو البحث)، لذلك احذف النص السري باستخدام «تنقيح PDF». للتغييرات الكبيرة، حوّل PDF إلى Word وعدّله هناك ثم احفظه PDF من جديد.',
          de: 'Klicken Sie auf vorhandenen Text, um ihn zu korrigieren. Der neue Text wird in der aus der Liste von 12 gewählten Schrift geschrieben und kann daher von der Originalschrift des Dokuments abweichen. Der alte Text wird von einem Rechteck in der Hintergrundfarbe verdeckt, bleibt aber in der Datei (er erscheint beim Kopieren und Suchen); vertraulichen Text entfernen Sie daher mit „PDF schwärzen“. Bei größeren Änderungen wandeln Sie das PDF besser in Word um, bearbeiten es dort und speichern es wieder als PDF.',
          en: 'Click existing text to correct it. The new text is written in the font you pick from the list of 12, so it may differ from the document’s original font. The old text is covered by a rectangle in the background colour but stays in the file (it shows up when you copy or search), so remove confidential text with “Redact PDF”. For bigger changes, convert the PDF to Word, edit it there and save it as PDF again.',
          es: 'Haz clic en el texto existente para corregirlo. El texto nuevo se escribe con la fuente que elijas de la lista de 12, así que puede diferir de la fuente original del documento. El texto antiguo queda tapado por un rectángulo del color del fondo, pero sigue en el archivo (aparece al copiar o buscar), por eso elimina el texto confidencial con «Censurar PDF». Para cambios grandes, convierte el PDF a Word, edítalo allí y vuelve a guardarlo como PDF.',
          fa: 'برای اصلاح متن موجود روی آن کلیک کنید. متن تازه با قلمی نوشته می‌شود که از فهرست ۱۲ قلم انتخاب می‌کنید، پس ممکن است با قلم اصلی سند فرق داشته باشد. متن قبلی با مستطیلی به رنگ پس‌زمینه پوشانده می‌شود اما در فایل می‌ماند (هنگام کپی یا جست‌وجو دیده می‌شود)، پس متن محرمانه را با «سانسور PDF» حذف کنید. برای تغییرهای بزرگ‌تر بهتر است PDF را به ورد تبدیل کنید، آنجا ویرایش کنید و دوباره به‌صورت PDF ذخیره کنید.',
          fr: 'Cliquez sur le texte existant pour le corriger. Le nouveau texte est écrit dans la police choisie parmi les 12 proposées, il peut donc différer de la police d’origine du document. L’ancien texte est masqué par un rectangle de la couleur du fond mais reste dans le fichier (il apparaît lors d’une copie ou d’une recherche) : supprimez donc le texte confidentiel avec « Caviarder PDF ». Pour des changements importants, convertissez le PDF en Word, modifiez-le puis réenregistrez-le en PDF.',
          hi: 'मौजूदा टेक्स्ट सुधारने के लिए उस पर क्लिक करें। नया टेक्स्ट 12 की सूची में से चुने फ़ॉन्ट में लिखा जाता है, इसलिए वह दस्तावेज़ के मूल फ़ॉन्ट से अलग हो सकता है। पुराना टेक्स्ट पृष्ठभूमि रंग के आयत से ढक जाता है, लेकिन फ़ाइल में बना रहता है (कॉपी या खोज करने पर दिखता है), इसलिए गोपनीय टेक्स्ट “PDF रिडैक्ट करें” से हटाएँ। बड़े बदलावों के लिए PDF को Word में बदलें, वहाँ संपादित करें और फिर से PDF के रूप में सहेजें।',
          is: 'Smelltu á texta sem fyrir er til að laga hann. Nýi textinn er skrifaður með letrinu sem þú velur af listanum með 12, svo hann getur verið frábrugðinn upprunalegu letri skjalsins. Gamli textinn er hulinn rétthyrningi í bakgrunnslit en verður áfram í skránni (hann birtist við afritun og leit), svo fjarlægðu trúnaðartexta með „Maska PDF“. Við stærri breytingar er einfaldara að breyta PDF í Word, laga það þar og vista aftur sem PDF.',
          it: 'Fai clic sul testo esistente per correggerlo. Il nuovo testo è scritto con il carattere scelto dall’elenco di 12, quindi può differire da quello originale del documento. Il vecchio testo viene coperto da un rettangolo del colore di sfondo ma resta nel file (compare quando copi o cerchi), perciò elimina il testo riservato con «Oscurare PDF». Per modifiche più ampie conviene convertire il PDF in Word, modificarlo lì e salvarlo di nuovo come PDF.',
          ja: '既存のテキストをクリックすると修正できます。新しいテキストは 12 種類のリストから選んだフォントで書かれるため、文書の元のフォントと異なることがあります。元のテキストは背景色の四角形で隠されますが、ファイルには残ります（コピーや検索で現れます）。機密のテキストは「PDF墨消し」で削除してください。大きな変更は、PDF を Word に変換して編集し、再び PDF として保存するほうが簡単です。',
          no: 'Klikk på eksisterende tekst for å rette den. Den nye teksten skrives med skrifttypen du velger blant de 12, så den kan avvike fra dokumentets opprinnelige skrift. Den gamle teksten dekkes av et rektangel i bakgrunnsfargen, men blir liggende i filen (den vises når du kopierer eller søker), så fjern konfidensiell tekst med «Sensurer PDF». Ved større endringer er det enklere å gjøre PDF-en om til Word, redigere der og lagre som PDF igjen.',
          pl: 'Kliknij istniejący tekst, aby go poprawić. Nowy tekst jest pisany czcionką wybraną z listy 12, więc może różnić się od oryginalnej czcionki dokumentu. Stary tekst zakrywa prostokąt w kolorze tła, ale zostaje w pliku (pojawia się przy kopiowaniu i wyszukiwaniu), dlatego poufny tekst usuwaj narzędziem „Redaguj PDF”. Przy większych zmianach wygodniej zamienić PDF na Word, poprawić go tam i zapisać ponownie jako PDF.',
          pt: 'Clique no texto existente para o corrigir. O texto novo é escrito com o tipo de letra que escolher da lista de 12, por isso pode ser diferente do original do documento. O texto antigo fica tapado por um retângulo da cor do fundo, mas continua no ficheiro (aparece ao copiar ou pesquisar); por isso remova texto confidencial com «Ocultar PDF». Para alterações maiores, converta o PDF em Word, edite-o lá e guarde-o novamente como PDF.',
          sv: 'Klicka på befintlig text för att rätta den. Den nya texten skrivs med typsnittet du väljer bland de 12, så den kan skilja sig från dokumentets ursprungliga typsnitt. Den gamla texten täcks av en rektangel i bakgrundsfärgen men finns kvar i filen (den syns när du kopierar eller söker), så ta bort konfidentiell text med ”Svärta PDF”. Vid större ändringar är det enklare att göra om PDF:en till Word, redigera där och spara som PDF igen.',
          tr: 'Düzeltmek için mevcut metne tıklayın. Yeni metin 12’lik listeden seçtiğiniz yazı tipiyle yazılır, bu yüzden belgenin özgün yazı tipinden farklı olabilir. Eski metin arka plan rengindeki bir dikdörtgenle örtülür ama dosyada kalır (kopyalarken veya ararken görünür); bu nedenle gizli metni “PDF Sansürle” ile kaldırın. Büyük değişiklikler için PDF’i Word’e çevirip orada düzenlemek ve yeniden PDF olarak kaydetmek daha kolaydır.',
          zh: '点击现有文字即可修改。新文字使用你从 12 种字体列表中选择的字体书写，因此可能与文档原来的字体不同。原文字会被一个背景色矩形盖住，但仍留在文件中（复制或搜索时会出现），所以机密文字请用“涂黑PDF”删除。如果改动较多，更方便的做法是把 PDF 转成 Word，在 Word 中修改后再保存为 PDF。',
        },
      },
    ],
  },
  {
    key: 'convert', icon: 'swap',
    label: { pl: 'Konwersja PDF', en: 'Convert PDF' , de: 'PDF konvertieren', es: 'Convertir PDF', pt: 'Conversão PDF', no: 'PDF-konvertering', sv: 'PDF-konvertering', fr: 'Conversion PDF', ar: 'تحويل PDF', fa: 'تبدیل PDF', tr: 'PDF Dönüştürme', hi: 'PDF रूपांतरण', is: 'PDF umbreyting', it: 'Conversione PDF', ja: 'PDF変換', zh: 'PDF转换'},
    items: [
      { key: 'word-formatting', href: '/pdf-to-word',
        q: { pl: 'Konwersja PDF do Word traci formatowanie?', en: 'PDF to Word conversion loses formatting?' , de: 'Die Konvertierung von PDF zu Word verliert die Formatierung?', es: '¿La conversión de PDF a Word pierde el formato?', pt: 'A conversão de PDF para Word perde a formatação?', no: 'Mister PDF-til-Word-konverteringen formateringen?', sv: 'Förlorar PDF-till-Word-konverteringen formateringen?', fr: 'La conversion PDF vers Word perd la mise en forme ?', ar: 'التحويل من PDF إلى Word يفقد التنسيق؟', fa: 'تبدیل PDF به Word قالب‌بندی را از دست می‌دهد؟', tr: 'PDF\'den Word\'e dönüştürme biçimlendirmeyi kaybediyor mu?', hi: 'क्या PDF से Word रूपांतरण फ़ॉर्मेटिंग खो देता है?', is: 'Týnir umbreytingin úr PDF í Word sniði?', it: 'La conversione da PDF a Word perde la formattazione?', ja: 'PDFからWordへの変換で書式が失われますか？', zh: 'PDF转Word会丢失格式？'},
        a: { pl: 'Pewna utrata formatowania przy konwersji PDF do Word jest naturalna — PDF nie przechowuje informacji o stylach tak jak dokument Word. Tabele, kolumny i zaawansowane układy mogą wymagać ręcznej korekty w Wordzie. Im prostszy układ PDF, tym lepszy wynik konwersji.', en: 'Some formatting loss during PDF to Word conversion is normal — PDF doesn\'t store style information like a Word document. Tables, columns and complex layouts may need manual adjustment in Word. The simpler the PDF layout, the better the conversion result.' , de: 'Ein gewisser Formatierungsverlust bei der Konvertierung von PDF zu Word ist normal – PDF speichert keine Stilinformationen wie ein Word-Dokument. Tabellen, Spalten und komplexe Layouts müssen möglicherweise manuell in Word angepasst werden. Je einfacher das PDF-Layout, desto besser das Konvertierungsergebnis.', es: 'Cierta pérdida de formato durante la conversión de PDF a Word es normal: el PDF no almacena información de estilos como un documento de Word. Las tablas, columnas y diseños complejos pueden requerir un ajuste manual en Word. Cuanto más simple sea el diseño del PDF, mejor será el resultado de la conversión.', pt: 'É normal perder alguma formatação durante a conversão de PDF para Word — o PDF não armazena informações de estilo como um documento do Word. As tabelas, colunas e esquemas complexos podem exigir ajustes manuais no Word. Quanto mais simples for o esquema do PDF, melhor será o resultado da conversão.', no: 'Noe tap av formatering under konvertering fra PDF til Word er normalt — PDF lagrer ikke stilinformasjon slik et Word-dokument gjør. Tabeller, kolonner og komplekse oppsett kan kreve manuell justering i Word. Jo enklere PDF-oppsettet er, desto bedre blir konverteringsresultatet.', sv: 'Visst formateringsförlust vid konvertering från PDF till Word är normalt — PDF lagrar inte stilinformation som ett Word-dokument gör. Tabeller, kolumner och komplexa layouter kan kräva manuell justering i Word. Ju enklare PDF-layouten är, desto bättre blir konverteringsresultatet.', fr: 'Une certaine perte de mise en forme lors de la conversion PDF vers Word est normale — le PDF ne stocke pas d\'informations de style comme le fait un document Word. Les tableaux, colonnes et mises en page complexes peuvent nécessiter un ajustement manuel dans Word. Plus la mise en page du PDF est simple, meilleur est le résultat de conversion.', ar: 'بعض فقدان التنسيق أثناء التحويل من PDF إلى Word أمر طبيعي — لا يخزن PDF معلومات الأنماط مثل مستند Word. قد تحتاج الجداول والأعمدة والتخطيطات المعقدة إلى تعديل يدوي في Word. كلما كان تخطيط PDF أبسط، كانت نتيجة التحويل أفضل.', fa: 'از دست دادن بخشی از قالب‌بندی در تبدیل PDF به Word طبیعی است — PDF اطلاعات سبک را مانند یک سند Word ذخیره نمی‌کند. جدول‌ها، ستون‌ها و چیدمان‌های پیچیده ممکن است به تنظیم دستی در Word نیاز داشته باشند. هرچه چیدمان PDF ساده‌تر باشد، نتیجه تبدیل بهتر است.', tr: 'PDF\'den Word\'e dönüştürme sırasında biçimlendirmenin bir kısmının kaybolması normaldir — PDF, bir Word belgesi gibi stil bilgisi saklamaz. Tablolar, sütunlar ve karmaşık düzenler Word\'de elle ayarlama gerektirebilir. PDF düzeni ne kadar basitse dönüştürme sonucu o kadar iyi olur.', hi: 'PDF से Word रूपांतरण के दौरान कुछ फ़ॉर्मेटिंग का नुकसान सामान्य है - PDF Word दस्तावेज़ की तरह शैली की जानकारी संग्रहीत नहीं करता है। तालिकाओं, कॉलम और जटिल लेआउट को Word में मैन्युअल समायोजन की आवश्यकता हो सकती है। PDF लेआउट जितना सरल होगा, रूपांतरण परिणाम उतना ही बेहतर होगा।', is: 'Eitthvert sniðtap við umbreytingu úr PDF í Word er eðlilegt — PDF geymir ekki sniðupplýsingar eins og Word-skjal. Töflur, dálkar og flókið skipulag geta þurft handvirka leiðréttingu í Word. Því einfaldara sem PDF-skipulagið er, því betri verður umbreytingin.', it: 'Una certa perdita di formattazione durante la conversione da PDF a Word è normale: il PDF non memorizza le informazioni sugli stili come fa un documento Word. Tabelle, colonne e layout complessi potrebbero richiedere una correzione manuale in Word. Più semplice è il layout del PDF, migliore sarà il risultato della conversione.', ja: 'PDFからWordへの変換中に書式が多少失われるのは正常です。PDFはWordドキュメントのようにスタイル情報を保存しないためです。表、列、複雑なレイアウトはWordで手動調整が必要になる場合があります。PDFのレイアウトがシンプルなほど、変換結果は良くなります。', zh: 'PDF转Word时丢失部分格式是正常的——PDF不像Word文档那样存储样式信息。表格、列和复杂布局可能需要在Word中手动调整。PDF布局越简单，转换效果越好。'},
      },
      { key: 'images-quality', href: '/pdf-to-images',
        q: { pl: 'Jakość obrazów z PDF jest niska?', en: 'Image quality from PDF is low?' , de: 'Die Bildqualität aus dem PDF ist niedrig?', es: '¿La calidad de las imágenes del PDF es baja?', pt: 'A qualidade das imagens do PDF é baixa?', no: 'Er bildekvaliteten fra PDF-en lav?', sv: 'Är bildkvaliteten från PDF-filen låg?', fr: 'La qualité des images issues du PDF est faible ?', ar: 'جودة الصور من PDF منخفضة؟', fa: 'کیفیت تصاویر حاصل از PDF پایین است؟', tr: 'PDF\'den alınan görüntü kalitesi düşük mü?', hi: 'क्या PDF से छवि गुणवत्ता कम है?', is: 'Er myndgæðið úr PDF lágt?', it: 'La qualità delle immagini dal PDF è bassa?', ja: 'PDFから抽出した画像の品質が低いですか？', zh: '从PDF导出的图像质量较低？'},
        a: {
          ar: 'المقياس الافتراضي 2، أي 144 DPI. للحصول على صور أوضح، ارفع المقياس إلى 3 أو 4 (216 أو 288 DPI) قبل التحويل. للصفحات التي تحتوي نصًا اختر PNG الذي يحافظ على وضوح الحروف، أما JPG فأنسب للصور الفوتوغرافية.',
          de: 'Die Standardskalierung ist 2, also 144 DPI. Für schärfere Bilder erhöhen Sie die Skalierung vor dem Umwandeln auf 3 oder 4 (216 oder 288 DPI). Für Seiten mit Text wählen Sie PNG, das Buchstaben scharf hält; JPG eignet sich besser für Fotos.',
          en: 'The default scale is 2, which is 144 DPI. For sharper images, raise the scale to 3 or 4 (216 or 288 DPI) before converting. For pages with text choose PNG, which keeps letters sharp; JPG suits photos better.',
          es: 'La escala predeterminada es 2, es decir, 144 DPI. Para imágenes más nítidas, sube la escala a 3 o 4 (216 o 288 DPI) antes de convertir. Para páginas con texto elige PNG, que mantiene las letras nítidas; JPG va mejor con fotos.',
          fa: 'مقیاس پیش‌فرض ۲ است، یعنی ۱۴۴ DPI. برای تصویرهای واضح‌تر، پیش از تبدیل مقیاس را به ۳ یا ۴ (۲۱۶ یا ۲۸۸ DPI) برسانید. برای صفحه‌های متنی PNG را انتخاب کنید که حروف را واضح نگه می‌دارد؛ JPG برای عکس مناسب‌تر است.',
          fr: 'L’échelle par défaut est 2, soit 144 DPI. Pour des images plus nettes, passez l’échelle à 3 ou 4 (216 ou 288 DPI) avant la conversion. Pour les pages contenant du texte, choisissez PNG, qui garde les lettres nettes ; le JPG convient mieux aux photos.',
          hi: 'डिफ़ॉल्ट स्केल 2 है, यानी 144 DPI। ज़्यादा स्पष्ट चित्रों के लिए बदलने से पहले स्केल 3 या 4 (216 या 288 DPI) करें। टेक्स्ट वाले पृष्ठों के लिए PNG चुनें, जो अक्षरों को साफ़ रखता है; फ़ोटो के लिए JPG बेहतर है।',
          is: 'Sjálfgefinn kvarði er 2, sem jafngildir 144 DPI. Fyrir skarpari myndir hækkarðu kvarðann í 3 eða 4 (216 eða 288 DPI) áður en þú umbreytir. Fyrir síður með texta velurðu PNG, sem heldur stöfum skörpum; JPG hentar betur fyrir ljósmyndir.',
          it: 'La scala predefinita è 2, cioè 144 DPI. Per immagini più nitide, porta la scala a 3 o 4 (216 o 288 DPI) prima della conversione. Per le pagine con testo scegli PNG, che mantiene le lettere nitide; il JPG è più adatto alle foto.',
          ja: 'スケールの初期値は 2 で、144 DPI に相当します。より鮮明な画像にするには、変換前にスケールを 3 または 4（216 または 288 DPI）に上げてください。文字のあるページには文字がくっきり残る PNG を、写真には JPG を選ぶのがおすすめです。',
          no: 'Standard skala er 2, altså 144 DPI. For skarpere bilder øker du skalaen til 3 eller 4 (216 eller 288 DPI) før du konverterer. For sider med tekst velger du PNG, som holder bokstavene skarpe; JPG passer bedre til bilder.',
          pl: 'Domyślna skala to 2, czyli 144 DPI. Aby obrazy były ostrzejsze, przed konwersją zwiększ skalę do 3 lub 4 (216 lub 288 DPI). Dla stron z tekstem wybierz PNG, który zachowuje ostre litery; JPG lepiej sprawdza się przy zdjęciach.',
          pt: 'A escala predefinida é 2, ou seja, 144 DPI. Para imagens mais nítidas, aumente a escala para 3 ou 4 (216 ou 288 DPI) antes de converter. Para páginas com texto escolha PNG, que mantém as letras nítidas; o JPG adequa-se melhor a fotografias.',
          sv: 'Standardskalan är 2, alltså 144 DPI. För skarpare bilder höjer du skalan till 3 eller 4 (216 eller 288 DPI) innan du konverterar. För sidor med text väljer du PNG, som håller bokstäverna skarpa; JPG passar bättre för foton.',
          tr: 'Varsayılan ölçek 2’dir, yani 144 DPI. Daha keskin görüntüler için dönüştürmeden önce ölçeği 3 veya 4’e (216 veya 288 DPI) çıkarın. Metin içeren sayfalar için harfleri keskin tutan PNG’yi seçin; JPG fotoğraflara daha uygundur.',
          zh: '默认缩放比例为 2，即 144 DPI。如需更清晰的图片，请在转换前把缩放比例提高到 3 或 4（216 或 288 DPI）。有文字的页面请选择能保持文字清晰的 PNG；照片更适合 JPG。',
        },
      },
      { key: 'excel-tables', href: '/pdf-to-excel',
        q: { pl: 'Tabele z PDF nie przenoszą się poprawnie do Excela?', en: 'Tables from PDF don\'t transfer correctly to Excel?' , de: 'Tabellen aus PDF werden nicht korrekt nach Excel übertragen?', es: '¿Las tablas del PDF no se transfieren correctamente a Excel?', pt: 'As tabelas do PDF não são transferidas corretamente para o Excel?', no: 'Overføres ikke tabeller fra PDF riktig til Excel?', sv: 'Överförs inte tabeller från PDF korrekt till Excel?', fr: 'Les tableaux du PDF ne se transfèrent pas correctement vers Excel ?', ar: 'لا تنتقل الجداول من PDF إلى Excel بشكل صحيح؟', fa: 'جدول‌های PDF به درستی به Excel منتقل نمی‌شوند؟', tr: 'PDF\'deki tablolar Excel\'e doğru aktarılmıyor mu?', hi: 'क्या PDF की तालिकाएँ Excel में सही ढंग से स्थानांतरित नहीं होती हैं?', is: 'Færast töflur úr PDF ekki rétt yfir í Excel?', it: 'Le tabelle dal PDF non vengono trasferite correttamente in Excel?', ja: 'PDFの表がExcelに正しく転送されませんか？', zh: 'PDF中的表格无法正确转移到Excel？'},
        a: { pl: 'Konwersja tabel z PDF do Excela działa najlepiej dla prostych tabel. Złożone tabele z połączonymi komórkami, kolorami i niestandardowym formatowaniem mogą wymagać ręcznej korekty. Jeśli dane są wyświetlane w jednej kolumnie zamiast w tabeli, spróbuj najpierw wyeksportować PDF do TXT, a potem zaimportować do Excela z podziałem na kolumny.', en: 'PDF to Excel table conversion works best for simple tables. Complex tables with merged cells, colors and custom formatting may need manual adjustment. If data appears in one column instead of a table, try exporting PDF to TXT first, then import to Excel with column splitting.' , de: 'Die Tabellenkonvertierung von PDF zu Excel funktioniert am besten bei einfachen Tabellen. Komplexe Tabellen mit verbundenen Zellen, Farben und benutzerdefinierter Formatierung müssen möglicherweise manuell angepasst werden. Wenn die Daten in einer Spalte statt in einer Tabelle erscheinen, versuchen Sie, das PDF zuerst nach TXT zu exportieren und es dann mit Spaltentrennung in Excel zu importieren.', es: 'La conversión de tablas de PDF a Excel funciona mejor con tablas simples. Las tablas complejas con celdas combinadas, colores y formato personalizado pueden requerir un ajuste manual. Si los datos aparecen en una sola columna en lugar de una tabla, pruebe a exportar primero el PDF a TXT y luego importarlo a Excel con división de columnas.', pt: 'A conversão de tabelas de PDF para Excel funciona melhor com tabelas simples. As tabelas complexas com células fundidas, cores e formatação personalizada podem exigir ajustes manuais. Se os dados aparecerem numa única coluna em vez de uma tabela, experimente primeiro exportar o PDF para TXT e depois importá-lo para o Excel com divisão de colunas.', no: 'Konvertering av tabeller fra PDF til Excel fungerer best for enkle tabeller. Komplekse tabeller med sammenslåtte celler, farger og egendefinert formatering kan kreve manuell justering. Hvis dataene vises i én kolonne i stedet for en tabell, prøv å eksportere PDF-en til TXT først, og importer den deretter til Excel med kolonnedeling.', sv: 'Konvertering av tabeller från PDF till Excel fungerar bäst för enkla tabeller. Komplexa tabeller med sammanslagna celler, färger och anpassad formatering kan kräva manuell justering. Om data visas i en enda kolumn i stället för en tabell, prova att exportera PDF-filen till TXT först och importera den sedan till Excel med kolumnavgränsning.', fr: 'La conversion de tableaux PDF vers Excel fonctionne mieux pour les tableaux simples. Les tableaux complexes avec des cellules fusionnées, des couleurs et une mise en forme personnalisée peuvent nécessiter un ajustement manuel. Si les données apparaissent dans une seule colonne au lieu d\'un tableau, essayez d\'exporter le PDF en TXT d\'abord, puis importez-le dans Excel avec une séparation par colonnes.', ar: 'يعمل تحويل الجداول من PDF إلى Excel بشكل أفضل مع الجداول البسيطة. قد تحتاج الجداول المعقدة ذات الخلايا المدمجة والألوان والتنسيق المخصص إلى تعديل يدوي. إذا ظهرت البيانات في عمود واحد بدلاً من جدول، جرّب تصدير PDF إلى TXT أولاً، ثم استوردها إلى Excel مع تقسيم الأعمدة.', fa: 'تبدیل جدول از PDF به Excel برای جدول‌های ساده بهترین عملکرد را دارد. جدول‌های پیچیده با سلول‌های ادغام‌شده، رنگ‌ها و قالب‌بندی سفارشی ممکن است به تنظیم دستی نیاز داشته باشند. اگر داده‌ها به جای جدول در یک ستون ظاهر می‌شوند، ابتدا PDF را به TXT صادر کنید و سپس با تفکیک ستون‌ها به Excel وارد کنید.', tr: 'PDF\'den Excel\'e tablo dönüştürme, basit tablolar için en iyi şekilde çalışır. Birleştirilmiş hücreler, renkler ve özel biçimlendirme içeren karmaşık tablolar elle ayarlama gerektirebilir. Veriler tablo yerine tek bir sütunda görünüyorsa önce PDF\'yi TXT olarak dışa aktarın, ardından sütunları bölerek Excel\'e içe aktarmayı deneyin.', hi: 'PDF से Excel तालिका रूपांतरण सरल तालिकाओं के लिए सबसे अच्छा काम करता है। विलय की गई कोशिकाओं, रंगों और कस्टम फ़ॉर्मेटिंग वाली जटिल तालिकाओं को मैन्युअल समायोजन की आवश्यकता हो सकती है। यदि डेटा तालिका के बजाय एक कॉलम में दिखाई देता है, तो पहले PDF को TXT में निर्यात करें, फिर कॉलम विभाजन के साथ Excel में आयात करें।', is: 'Töfluumbreyting úr PDF í Excel virkar best fyrir einfaldar töflur. Flóknar töflur með sameinuðum reitum, litum og sérsniðnu sniði geta þurft handvirka leiðréttingu. Ef gögnin birtast í einum dálki í stað töflu skaltu prófa að flytja PDF í TXT fyrst og flytja síðan inn í Excel með dálkaskiptingu.', it: 'La conversione delle tabelle da PDF a Excel funziona meglio con tabelle semplici. Le tabelle complesse con celle unite, colori e formattazione personalizzata potrebbero richiedere una correzione manuale. Se i dati appaiono in una sola colonna invece che in una tabella, prova prima a esportare il PDF in TXT e poi a importarlo in Excel con la divisione in colonne.', ja: 'PDFからExcelへの表の変換は、単純な表で最もよく機能します。結合セル、色、カスタム書式を含む複雑な表は、手動調整が必要な場合があります。データが表ではなく1つの列に表示される場合は、まずPDFをTXTにエクスポートし、列の分割を使用してExcelにインポートしてみてください。', zh: 'PDF转Excel的表格转换最适合简单表格。带有合并单元格、颜色和自定义格式的复杂表格可能需要手动调整。如果数据显示在一列中而不是表格中，请先尝试将PDF导出为TXT，然后按列拆分导入Excel。'},
      },
      { key: 'ocr-notext', href: '/ocr-pdf',
        q: { pl: 'OCR nie rozpoznaje tekstu lub rozpoznaje go błędnie?', en: 'OCR doesn\'t recognize text or recognizes it incorrectly?' , de: 'OCR erkennt Text nicht oder erkennt ihn falsch?', es: '¿El OCR no reconoce el texto o lo reconoce incorrectamente?', pt: 'O OCR não reconhece o texto ou reconhece-o incorretamente?', no: 'Gjenkjenner ikke OCR teksten, eller gjenkjenner den feil?', sv: 'Känner OCR inte igen texten, eller känner den igen den fel?', fr: 'L\'OCR ne reconnaît pas le texte, ou le reconnaît de manière incorrecte ?', ar: 'لا يتعرف OCR على النص أو يتعرف عليه بشكل غير صحيح؟', fa: 'OCR متن را تشخیص نمی‌دهد یا آن را به اشتباه تشخیص می‌دهد؟', tr: 'OCR metni tanımıyor veya yanlış mı tanıyor?', hi: 'क्या OCR टेक्स्ट को पहचान नहीं पाता है या गलत पहचानता है?', is: 'Þekkir OCR ekki textann eða þekkir hann ranglega?', it: 'L\'OCR non riconosce il testo o lo riconosce in modo errato?', ja: 'OCRがテキストを認識しないか、誤って認識しますか？', zh: 'OCR无法识别文本或识别有误？'},
        a: {
          ar: 'يعمل التعرف الضوئي على الحروف بأفضل شكل مع المسح الواضح. تحقق من: (1) الدقة: امسح بدقة 300 DPI. (2) استقامة الصفحات: قوّم المسوحات المائلة قبل التعرف. (3) الكتابة اليدوية: لا يتعرف عليها. (4) اللغة: اختر لغة المستند من قائمة اللغات الثلاث والثلاثين قبل البدء، فاختيار لغة خاطئة يضعف التعرف كثيرًا. (5) الخطوط الزخرفية: قد تُقرأ بشكل خاطئ.',
          de: 'OCR funktioniert am besten mit klaren Scans. Prüfen Sie: (1) Auflösung — scannen Sie mit 300 DPI. (2) Gerade Seiten — richten Sie schiefe Scans vor der OCR aus. (3) Handschrift — OCR erkennt sie nicht. (4) Sprache — wählen Sie vor dem Start die Sprache des Dokuments aus der Liste von 33; eine falsche Sprache verschlechtert die Erkennung deutlich. (5) Zierschriften — sie können falsch gelesen werden.',
          en: 'OCR works best on clear scans. Check: (1) Resolution — scan at 300 DPI. (2) Straight pages — straighten crooked scans before OCR. (3) Handwriting — OCR does not recognise it. (4) Language — pick the document’s language from the list of 33 before you start; the wrong language makes recognition much worse. (5) Decorative fonts — they may be read incorrectly.',
          es: 'El OCR funciona mejor con escaneos nítidos. Comprueba: (1) Resolución: escanea a 300 DPI. (2) Páginas rectas: endereza los escaneos torcidos antes del OCR. (3) Escritura a mano: el OCR no la reconoce. (4) Idioma: elige el idioma del documento de la lista de 33 antes de empezar; un idioma equivocado empeora mucho el reconocimiento. (5) Fuentes decorativas: pueden leerse mal.',
          fa: 'OCR روی اسکن‌های واضح بهترین نتیجه را دارد. بررسی کنید: (1) وضوح — با ۳۰۰ DPI اسکن کنید. (2) صاف بودن صفحه — اسکن‌های کج را پیش از OCR صاف کنید. (3) دست‌خط — OCR دست‌خط را تشخیص نمی‌دهد. (4) زبان — پیش از شروع، زبان سند را از فهرست ۳۳ زبان انتخاب کنید؛ زبان نادرست تشخیص را بسیار بدتر می‌کند. (5) قلم‌های تزئینی — ممکن است نادرست خوانده شوند.',
          fr: 'L’OCR fonctionne le mieux sur des scans nets. Vérifiez : (1) Résolution : numérisez à 300 DPI. (2) Pages droites : redressez les scans de travers avant l’OCR. (3) Écriture manuscrite : l’OCR ne la reconnaît pas. (4) Langue : choisissez la langue du document parmi les 33 avant de commencer ; une mauvaise langue dégrade fortement la reconnaissance. (5) Polices décoratives : elles peuvent être mal lues.',
          hi: 'OCR साफ़ स्कैन पर सबसे अच्छा काम करता है। जाँचें: (1) रिज़ॉल्यूशन — 300 DPI पर स्कैन करें। (2) सीधे पृष्ठ — OCR से पहले टेढ़े स्कैन सीधे करें। (3) हस्तलिपि — OCR उसे नहीं पहचानता। (4) भाषा — शुरू करने से पहले 33 की सूची में से दस्तावेज़ की भाषा चुनें; गलत भाषा पहचान को काफ़ी खराब कर देती है। (5) सजावटी फ़ॉन्ट — वे गलत पढ़े जा सकते हैं।',
          is: 'OCR virkar best á skýrum skönnunum. Athugaðu: (1) Upplausn — skannaðu í 300 DPI. (2) Beinar síður — réttu skakkar skannanir af áður en þú keyrir OCR. (3) Handskrift — OCR þekkir hana ekki. (4) Tungumál — veldu tungumál skjalsins af listanum með 33 áður en þú byrjar; rangt tungumál spillir greiningunni verulega. (5) Skrautletur — það getur verið lesið rangt.',
          it: 'L’OCR funziona meglio con scansioni nitide. Controlla: (1) Risoluzione: scansiona a 300 DPI. (2) Pagine dritte: raddrizza le scansioni storte prima dell’OCR. (3) Scrittura a mano: l’OCR non la riconosce. (4) Lingua: prima di iniziare scegli la lingua del documento dall’elenco di 33; una lingua sbagliata peggiora molto il riconoscimento. (5) Caratteri decorativi: possono essere letti male.',
          ja: 'OCR は鮮明なスキャンで最もよく機能します。確認してください：(1) 解像度 — 300 DPI でスキャンする。(2) まっすぐなページ — 傾いたスキャンは OCR の前に補正する。(3) 手書き — OCR は手書き文字を認識しません。(4) 言語 — 開始前に 33 言語のリストから文書の言語を選ぶ。言語を間違えると認識精度が大きく下がります。(5) 装飾的なフォント — 誤って読み取られることがあります。',
          no: 'OCR fungerer best på tydelige skanninger. Sjekk: (1) Oppløsning — skann med 300 DPI. (2) Rette sider — rett opp skjeve skanninger før OCR. (3) Håndskrift — OCR gjenkjenner den ikke. (4) Språk — velg dokumentets språk i listen med 33 før du starter; feil språk gjør gjenkjenningen mye dårligere. (5) Dekorative skrifter — de kan bli lest feil.',
          pl: 'OCR działa najlepiej na wyraźnych skanach. Sprawdź: (1) Rozdzielczość — skanuj w 300 DPI. (2) Proste strony — wyprostuj krzywe skany przed OCR. (3) Pismo odręczne — OCR go nie rozpoznaje. (4) Język — przed rozpoczęciem wybierz język dokumentu z listy 33; zły język wyraźnie pogarsza rozpoznawanie. (5) Czcionki ozdobne — mogą być odczytane błędnie.',
          pt: 'O OCR funciona melhor com digitalizações nítidas. Verifique: (1) Resolução: digitalize a 300 DPI. (2) Páginas direitas: endireite as digitalizações tortas antes do OCR. (3) Letra manuscrita: o OCR não a reconhece. (4) Idioma: antes de começar, escolha o idioma do documento na lista de 33; um idioma errado piora muito o reconhecimento. (5) Tipos de letra decorativos: podem ser lidos incorretamente.',
          sv: 'OCR fungerar bäst på tydliga skanningar. Kontrollera: (1) Upplösning — skanna i 300 DPI. (2) Raka sidor — räta upp sneda skanningar före OCR. (3) Handskrift — OCR känner inte igen den. (4) Språk — välj dokumentets språk i listan med 33 innan du börjar; fel språk försämrar igenkänningen kraftigt. (5) Dekorativa typsnitt — de kan läsas fel.',
          tr: 'OCR en iyi net taramalarda çalışır. Kontrol edin: (1) Çözünürlük — 300 DPI’da tarayın. (2) Düz sayfalar — eğri taramaları OCR’den önce düzeltin. (3) El yazısı — OCR el yazısını tanımaz. (4) Dil — başlamadan önce belgenin dilini 33 dillik listeden seçin; yanlış dil tanımayı ciddi biçimde kötüleştirir. (5) Süslü yazı tipleri — yanlış okunabilir.',
          zh: 'OCR 在清晰的扫描件上效果最好。请检查：(1) 分辨率：用 300 DPI 扫描。(2) 页面是否端正：OCR 前先把歪斜的扫描件摆正。(3) 手写：OCR 无法识别手写文字。(4) 语言：开始前从 33 种语言的列表中选择文档的语言；选错语言会使识别明显变差。(5) 装饰字体：可能被识别错误。',
        },
      },
      { key: 'html-noresponse', href: '/html-to-pdf',
        q: { pl: 'Konwersja URL do PDF nie działa?', en: 'URL to PDF conversion doesn\'t work?' , de: 'Die Konvertierung von URL zu PDF funktioniert nicht?', es: '¿La conversión de URL a PDF no funciona?', pt: 'A conversão de URL para PDF não funciona?', no: 'Fungerer ikke URL-til-PDF-konverteringen?', sv: 'Fungerar inte URL-till-PDF-konverteringen?', fr: 'La conversion URL vers PDF ne fonctionne pas ?', ar: 'لا يعمل التحويل من URL إلى PDF؟', fa: 'تبدیل URL به PDF کار نمی‌کند؟', tr: 'URL\'den PDF\'e dönüştürme çalışmıyor mu?', hi: 'क्या URL से PDF रूपांतरण काम नहीं करता है?', is: 'Virkar umbreytingin úr URL í PDF ekki?', it: 'La conversione da URL a PDF non funziona?', ja: 'URLからPDFへの変換が機能しませんか？', zh: 'URL转PDF不起作用？'},
        a: {
          ar: 'يجلب تحويل URL إلى PDF الصفحة عبر خادمنا ويحتفظ بنصها فقط. قد يفشل مع الصفحات التي تتطلب تسجيل الدخول أو تحظر الزوار الآليين أو تبني محتواها بلغة JavaScript أو تعيد التوجيه إلى عنوان آخر، وفي هذه الحالة أدخل العنوان النهائي من شريط عنوان المتصفح. لا تُجلب الصفحات التي يتجاوز حجمها 100 ميغابايت ولا عناوين الشبكات الخاصة. يمكنك أيضًا نسخ شيفرة HTML للصفحة إلى «HTML إلى PDF» الذي يحافظ على العناوين والقوائم والجداول.',
          de: 'URL zu PDF ruft die Seite über unseren Server ab und behält nur ihren Text. Es kann bei Seiten scheitern, die eine Anmeldung verlangen, automatische Besucher blockieren, ihren Inhalt per JavaScript aufbauen oder auf eine andere Adresse umleiten — geben Sie dann die endgültige Adresse aus der Adressleiste des Browsers ein. Seiten über 100 MB und Adressen aus privaten Netzen werden nicht abgerufen. Sie können auch den HTML-Code der Seite in „HTML zu PDF“ kopieren, das Überschriften, Listen und Tabellen erhält.',
          en: 'URL to PDF fetches the page through our server and keeps only its text. It may fail for pages that require signing in, block automated visitors, build their content with JavaScript or redirect to another address — in that case enter the final address from your browser’s address bar. Pages larger than 100 MB and private network addresses are not fetched. You can also copy the page’s HTML code into “HTML to PDF”, which keeps headings, lists and tables.',
          es: 'URL a PDF descarga la página a través de nuestro servidor y conserva solo su texto. Puede fallar con páginas que piden iniciar sesión, bloquean visitas automáticas, crean su contenido con JavaScript o redirigen a otra dirección; en ese caso escribe la dirección final de la barra del navegador. No se descargan páginas de más de 100 MB ni direcciones de redes privadas. También puedes copiar el código HTML de la página en «HTML a PDF», que conserva títulos, listas y tablas.',
          fa: 'تبدیل URL به PDF صفحه را از طریق سرور ما دریافت می‌کند و فقط متن آن را نگه می‌دارد. ممکن است برای صفحه‌هایی که ورود می‌خواهند، بازدیدکنندهٔ خودکار را مسدود می‌کنند، محتوا را با JavaScript می‌سازند یا به نشانی دیگری هدایت می‌کنند کار نکند؛ در این حالت نشانی نهایی را از نوار نشانی مرورگر وارد کنید. صفحه‌های بزرگ‌تر از ۱۰۰ مگابایت و نشانی‌های شبکهٔ خصوصی دریافت نمی‌شوند. همچنین می‌توانید کد HTML صفحه را در «HTML به PDF» کپی کنید که سرتیترها، فهرست‌ها و جدول‌ها را حفظ می‌کند.',
          fr: 'URL vers PDF récupère la page via notre serveur et n’en garde que le texte. Cela peut échouer pour les pages qui exigent une connexion, bloquent les visiteurs automatiques, construisent leur contenu en JavaScript ou redirigent vers une autre adresse ; saisissez alors l’adresse finale affichée dans la barre du navigateur. Les pages de plus de 100 Mo et les adresses de réseaux privés ne sont pas récupérées. Vous pouvez aussi copier le code HTML de la page dans « HTML vers PDF », qui conserve titres, listes et tableaux.',
          hi: 'URL को PDF में बदलना पेज को हमारे सर्वर से लाता है और केवल उसका टेक्स्ट रखता है। यह उन पेजों पर विफल हो सकता है जिन्हें साइन-इन चाहिए, जो स्वचालित आगंतुकों को रोकते हैं, अपनी सामग्री JavaScript से बनाते हैं या किसी दूसरे पते पर भेजते हैं — ऐसे में ब्राउज़र के एड्रेस बार से अंतिम पता दर्ज करें। 100 MB से बड़े पेज और निजी नेटवर्क के पते नहीं लाए जाते। आप पेज का HTML कोड “HTML को PDF में” में भी कॉपी कर सकते हैं, जो शीर्षक, सूचियाँ और तालिकाएँ बनाए रखता है।',
          is: 'URL í PDF sækir síðuna í gegnum netþjón okkar og heldur aðeins textanum. Það getur mistekist fyrir síður sem krefjast innskráningar, loka á sjálfvirka gesti, byggja efnið með JavaScript eða vísa á aðra slóð — sláðu þá inn endanlegu slóðina úr veffangastiku vafrans. Síður stærri en 100 MB og vistföng á einkanetum eru ekki sótt. Þú getur líka afritað HTML-kóða síðunnar í „HTML í PDF“, sem heldur fyrirsögnum, listum og töflum.',
          it: 'URL in PDF scarica la pagina tramite il nostro server e ne conserva solo il testo. Può non funzionare con pagine che richiedono l’accesso, bloccano i visitatori automatici, costruiscono il contenuto con JavaScript o reindirizzano a un altro indirizzo: in questo caso inserisci l’indirizzo finale dalla barra del browser. Le pagine oltre 100 MB e gli indirizzi di reti private non vengono scaricati. Puoi anche copiare il codice HTML della pagina in «HTML in PDF», che mantiene titoli, elenchi e tabelle.',
          ja: 'URL から PDF への変換は、当サイトのサーバーを通してページを取得し、そのテキストだけを残します。ログインが必要なページ、自動アクセスをブロックするページ、JavaScript で内容を作るページ、別のアドレスへリダイレクトするページでは失敗することがあります。その場合はブラウザーのアドレスバーに表示される最終的なアドレスを入力してください。100 MB を超えるページやプライベートネットワークのアドレスは取得しません。ページの HTML コードを、見出し・リスト・表を保つ「HTMLをPDFに変換」に貼り付ける方法もあります。',
          no: 'URL til PDF henter siden via serveren vår og beholder bare teksten. Det kan mislykkes for sider som krever pålogging, blokkerer automatiske besøkende, bygger innholdet med JavaScript eller videresender til en annen adresse — skriv da inn den endelige adressen fra nettleserens adresselinje. Sider større enn 100 MB og adresser i private nettverk hentes ikke. Du kan også kopiere sidens HTML-kode inn i «HTML til PDF», som beholder overskrifter, lister og tabeller.',
          pl: 'URL do PDF pobiera stronę przez nasz serwer i zachowuje tylko jej tekst. Może nie zadziałać dla stron wymagających logowania, blokujących automatyczne wizyty, budujących treść skryptami JavaScript albo przekierowujących pod inny adres — wtedy wpisz adres końcowy z paska przeglądarki. Strony większe niż 100 MB i adresy z sieci prywatnej nie są pobierane. Możesz też skopiować kod HTML strony do narzędzia „HTML do PDF”, które zachowuje nagłówki, listy i tabele.',
          pt: 'URL para PDF obtém a página através do nosso servidor e mantém apenas o seu texto. Pode falhar em páginas que exigem início de sessão, bloqueiam visitas automáticas, constroem o conteúdo com JavaScript ou redirecionam para outro endereço; nesse caso, escreva o endereço final da barra do navegador. Não são obtidas páginas com mais de 100 MB nem endereços de redes privadas. Também pode copiar o código HTML da página para «HTML para PDF», que mantém títulos, listas e tabelas.',
          sv: 'URL till PDF hämtar sidan via vår server och behåller bara texten. Det kan misslyckas för sidor som kräver inloggning, blockerar automatiska besökare, bygger innehållet med JavaScript eller omdirigerar till en annan adress — ange då den slutliga adressen från webbläsarens adressfält. Sidor större än 100 MB och adresser i privata nätverk hämtas inte. Du kan också kopiera sidans HTML-kod till ”HTML till PDF”, som behåller rubriker, listor och tabeller.',
          tr: "URL’den PDF’e dönüştürme sayfayı sunucumuz üzerinden alır ve yalnızca metnini korur. Oturum açma gerektiren, otomatik ziyaretçileri engelleyen, içeriğini JavaScript ile oluşturan veya başka bir adrese yönlendiren sayfalarda çalışmayabilir; bu durumda tarayıcının adres çubuğundaki son adresi girin. 100 MB’tan büyük sayfalar ve özel ağ adresleri alınmaz. Sayfanın HTML kodunu, başlıkları, listeleri ve tabloları koruyan “HTML'den PDF'e” aracına da kopyalayabilirsiniz.",
          zh: 'URL 转 PDF 通过我们的服务器获取网页，并只保留其中的文字。对于需要登录、屏蔽自动访问、用 JavaScript 生成内容或会跳转到其他地址的网页，可能无法转换；此时请输入浏览器地址栏中显示的最终地址。超过 100 MB 的网页和私有网络地址不会被获取。你也可以把网页的 HTML 代码复制到“HTML转PDF”中，它会保留标题、列表和表格。',
        },
      },
      { key: 'epub-layout', href: '/pdf-to-epub',
        q: { pl: 'EPUB z PDF wygląda inaczej niż oryginał?', en: 'EPUB from PDF looks different from the original?' , de: 'EPUB aus PDF sieht anders aus als das Original?', es: '¿El EPUB desde PDF se ve diferente del original?', pt: 'O EPUB a partir do PDF é diferente do original?', no: 'Ser EPUB fra PDF annerledes ut enn originalen?', sv: 'Ser EPUB från PDF annorlunda ut än originalet?', fr: 'L\'EPUB issu du PDF est différent de l\'original ?', ar: 'EPUB من PDF يبدو مختلفًا عن الأصل؟', fa: 'EPUB حاصل از PDF با نسخه اصلی متفاوت به نظر می‌رسد؟', tr: 'PDF\'den oluşturulan EPUB orijinalinden farklı mı görünüyor?', hi: 'क्या PDF से EPUB मूल से अलग दिखता है?', is: 'Lítur EPUB úr PDF öðruvísi út en upprunalega?', it: 'L\'EPUB dal PDF è diverso dall\'originale?', ja: 'PDFから作成したEPUBが元のドキュメントと異なって見えますか？', zh: '从PDF生成的EPUB与原文不同？'},
        a: { pl: 'To normalne — EPUB jest formatem typu "reflowable" (płynny), gdzie tekst dostosowuje się do rozmiaru ekranu, podczas gdy PDF ma stały układ. Obrazy, tabele i złożone układy mogą być przesunięte. Jeśli zależy Ci na oryginalnym układzie, pozostań przy PDF. EPUB lepiej nadaje się do czytania na czytnikach ebooków i telefonach.', en: 'This is normal — EPUB is a reflowable format where text adapts to screen size, while PDF has a fixed layout. Images, tables and complex layouts may be shifted. If you need the original layout, stay with PDF. EPUB is better for reading on ebook readers and phones.' , de: 'Das ist normal – EPUB ist ein umfließendes (reflowable) Format, bei dem sich der Text an die Bildschirmgröße anpasst, während PDF ein festes Layout hat. Bilder, Tabellen und komplexe Layouts können verschoben sein. Wenn Sie das ursprüngliche Layout benötigen, bleiben Sie bei PDF. EPUB eignet sich besser zum Lesen auf E-Book-Readern und Smartphones.', es: 'Esto es normal: EPUB es un formato reflowable en el que el texto se adapta al tamaño de la pantalla, mientras que PDF tiene un diseño fijo. Las imágenes, tablas y diseños complejos pueden desplazarse. Si necesita el diseño original, quédese con el PDF. EPUB es mejor para leer en lectores de libros electrónicos y teléfonos.', pt: 'Isto é normal — o EPUB é um formato refluível em que o texto se adapta ao tamanho do ecrã, enquanto o PDF tem um esquema fixo. As imagens, tabelas e esquemas complexos podem ser deslocadas. Se precisar do esquema original, fique com o PDF. O EPUB é melhor para leitura em leitores de livros eletrónicos e telemóveis.', no: 'Dette er normalt — EPUB er et reflowbart format der teksten tilpasser seg skjermstørrelsen, mens PDF har et fast oppsett. Bilder, tabeller og komplekse oppsett kan bli forskjøvet. Hvis du trenger det originale oppsettet, hold deg til PDF. EPUB er bedre for lesing på e-boklesere og telefoner.', sv: 'Detta är normalt — EPUB är ett reflowbart format där texten anpassar sig till skärmstorleken, medan PDF har en fast layout. Bilder, tabeller och komplexa layouter kan förskjutas. Om du behöver den ursprungliga layouten, håll dig till PDF. EPUB är bättre för läsning på e-bokläsare och telefoner.', fr: 'C\'est normal — l\'EPUB est un format fluide (reflowable) où le texte s\'adapte à la taille de l\'écran, tandis que le PDF a une mise en page fixe. Les images, tableaux et mises en page complexes peuvent être décalés. Si vous avez besoin de la mise en page d\'origine, restez en PDF. L\'EPUB est préférable pour la lecture sur liseuses et téléphones.', ar: 'هذا أمر طبيعي — EPUB هو تنسيق قابل لإعادة التدفق حيث يتكيف النص مع حجم الشاشة، بينما PDF له تخطيط ثابت. قد تُزاح الصور والجداول والتخطيطات المعقدة. إذا كنت بحاجة إلى التخطيط الأصلي، فابقَ مع PDF. EPUB أفضل للقراءة على قارئات الكتب الإلكترونية والهواتف.', fa: 'این طبیعی است — EPUB یک فرمت reflowable (جریان‌پذیر) است که در آن متن با اندازه صفحه نمایش سازگار می‌شود، در حالی که PDF چیدمان ثابتی دارد. تصاویر، جدول‌ها و چیدمان‌های پیچیده ممکن است جابه‌جا شوند. اگر به چیدمان اصلی نیاز دارید، با PDF بمانید. EPUB برای مطالعه در کتاب‌خوان‌های الکترونیکی و تلفن‌ها بهتر است.', tr: 'Bu normaldir — EPUB, metnin ekran boyutuna uyum sağladığı akışkan bir formattır, PDF ise sabit bir düzene sahiptir. Görseller, tablolar ve karmaşık düzenler kayabilir. Orijinal düzene ihtiyacınız varsa PDF\'de kalın. EPUB, e-kitap okuyucularda ve telefonlarda okumak için daha iyidir.', hi: 'यह सामान्य है - EPUB एक रीफ़्लो करने योग्य प्रारूप है जहाँ टेक्स्ट स्क्रीन के आकार के अनुसार ढल जाता है, जबकि PDF में एक निश्चित लेआउट होता है। छवियाँ, तालिकाएँ और जटिल लेआउट स्थानांतरित हो सकते हैं। यदि आपको मूल लेआउट चाहिए, तो PDF के साथ रहें। EPUB ईबुक रीडर और फ़ोन पर पढ़ने के लिए बेहतर है।', is: 'Þetta er eðlilegt — EPUB er endurflæðiformat (reflowable) þar sem textinn lagar sig að skjástærð, en PDF hefur fast skipulag. Myndir, töflur og flókið skipulag geta færst til. Ef þú þarft upprunalega skipulagið skaltu halda þig við PDF. EPUB er betra til lestrar á rafbókalesurum og símum.', it: 'È normale: l\'EPUB è un formato reflowable in cui il testo si adatta alle dimensioni dello schermo, mentre il PDF ha un layout fisso. Immagini, tabelle e layout complessi potrebbero essere spostati. Se hai bisogno del layout originale, resta con il PDF. L\'EPUB è migliore per la lettura su e-reader e telefoni.', ja: 'これは正常です。EPUBはリフロー型（reflowable）の形式で、テキストが画面サイズに合わせて調整される一方、PDFは固定レイアウトです。画像、表、複雑なレイアウトは位置がずれる場合があります。元のレイアウトが必要な場合は、PDFのままにしてください。EPUBは電子書籍リーダーやスマートフォンでの読書に適しています。', zh: '这是正常的——EPUB是可重排格式，文本会适应屏幕大小，而PDF具有固定布局。图像、表格和复杂布局可能会移位。如果您需要原始布局，请继续使用PDF。EPUB更适合在电子书阅读器和手机上阅读。'},
      },
    ],
  },
  {
    key: 'secure', icon: 'key',
    label: { pl: 'Zabezpieczenia PDF', en: 'PDF Security' , de: 'PDF-Sicherheit', es: 'Seguridad de PDF', pt: 'Segurança PDF', no: 'PDF-sikkerhet', sv: 'PDF-säkerhet', fr: 'Sécurité PDF', ar: 'أمان PDF', fa: 'امنیت PDF', tr: 'PDF Güvenliği', hi: 'PDF सुरक्षा', is: 'PDF öryggi', it: 'Sicurezza PDF', ja: 'PDFセキュリティ', zh: 'PDF安全'},
    items: [
      { key: 'protect-password', href: '/protect-pdf',
        q: { pl: 'Nie mogę otworzyć pliku po zabezpieczeniu?', en: 'Can\'t open the file after protecting?' , de: 'Die Datei lässt sich nach dem Schützen nicht öffnen?', es: '¿No puede abrir el archivo después de protegerlo?', pt: 'Não consegue abrir o ficheiro depois de o proteger?', no: 'Kan du ikke åpne filen etter at du har beskyttet den?', sv: 'Kan du inte öppna filen efter att du har skyddat den?', fr: 'Impossible d\'ouvrir le fichier après l\'avoir protégé ?', ar: 'لا يمكن فتح الملف بعد الحماية؟', fa: 'بعد از محافظت نمی‌توانم فایل را باز کنم؟', tr: 'Korumadan sonra dosyayı açamıyor musunuz?', hi: 'क्या सुरक्षा के बाद फ़ाइल नहीं खोल पा रहे हैं?', is: 'Get ég ekki opnað skrána eftir verndun?', it: 'Non riesci ad aprire il file dopo la protezione?', ja: '保護した後にファイルを開けませんか？', zh: '保护后无法打开文件？'},
        a: { pl: 'Zapisz hasło w bezpiecznym miejscu! OptimaPDF nie przechowuje haseł i nie ma możliwości ich odzyskania. Jeśli zapomniałeś hasła, nie ma sposobu na otwarcie pliku. Zalecamy: (1) Używaj haseł, które pamiętasz. (2) Zapisz hasło w menedżerze haseł. (3) Przed zabezpieczeniem zrób kopię oryginalnego pliku bez hasła.', en: 'Save your password in a safe place! OptimaPDF does not store passwords and cannot recover them. If you forget your password, there is no way to open the file. We recommend: (1) Use passwords you can remember. (2) Save the password in a password manager. (3) Keep a backup of the original file before protecting.' , de: 'Bewahren Sie Ihr Passwort an einem sicheren Ort auf! OptimaPDF speichert keine Passwörter und kann sie nicht wiederherstellen. Wenn Sie Ihr Passwort vergessen, gibt es keine Möglichkeit, die Datei zu öffnen. Wir empfehlen: (1) Verwenden Sie Passwörter, die Sie sich merken können. (2) Speichern Sie das Passwort in einem Passwort-Manager. (3) Erstellen Sie vor dem Schützen eine Sicherungskopie der Originaldatei.', es: '¡Guarde su contraseña en un lugar seguro! OptimaPDF no almacena contraseñas y no puede recuperarlas. Si olvida su contraseña, no hay forma de abrir el archivo. Recomendamos: (1) usar contraseñas que pueda recordar. (2) Guardar la contraseña en un administrador de contraseñas. (3) Hacer una copia de seguridad del archivo original antes de protegerlo.', pt: 'Guarde a sua palavra-passe num local seguro! O OptimaPDF não armazena palavras-passe e não pode recuperá-las. Se se esquecer da sua palavra-passe, não há forma de abrir o ficheiro. Recomendamos: (1) utilizar palavras-passe de que se lembre. (2) Guardar a palavra-passe num gestor de palavras-passe. (3) Manter uma cópia de segurança do ficheiro original antes de o proteger.', no: 'Lagre passordet ditt på et trygt sted! OptimaPDF lagrer ikke passord og kan ikke gjenopprette dem. Hvis du glemmer passordet, finnes det ingen måte å åpne filen på. Vi anbefaler: (1) Bruk passord du husker. (2) Lagre passordet i en passordbehandler. (3) Ta en sikkerhetskopi av originalfilen før du beskytter den.', sv: 'Spara ditt lösenord på en säker plats! OptimaPDF lagrar inte lösenord och kan inte återställa dem. Om du glömmer ditt lösenord finns det inget sätt att öppna filen. Vi rekommenderar: (1) Använd lösenord du kommer ihåg. (2) Spara lösenordet i en lösenordshanterare. (3) Ta en säkerhetskopia av originalfilen innan du skyddar den.', fr: 'Enregistrez votre mot de passe dans un endroit sûr ! OptimaPDF ne stocke pas les mots de passe et ne peut pas les récupérer. Si vous oubliez votre mot de passe, il n\'y a aucun moyen d\'ouvrir le fichier. Nous recommandons : (1) Utilisez des mots de passe que vous pouvez mémoriser. (2) Enregistrez le mot de passe dans un gestionnaire de mots de passe. (3) Conservez une sauvegarde du fichier original avant de le protéger.', ar: 'احفظ كلمة المرور في مكان آمن! لا يخزن OptimaPDF كلمات المرور ولا يمكنه استعادتها. إذا نسيت كلمة المرور، فلن تكون هناك طريقة لفتح الملف. نوصي بما يلي: (1) استخدم كلمات مرور يمكنك تذكرها. (2) احفظ كلمة المرور في مدير كلمات المرور. (3) احتفظ بنسخة احتياطية من الملف الأصلي قبل الحماية.', fa: 'رمز عبور خود را در یک مکان امن ذخیره کنید! OptimaPDF رمز‌های عبور را ذخیره نمی‌کند و نمی‌تواند آن‌ها را بازیابی کند. اگر رمز عبور خود را فراموش کنید، هیچ راهی برای باز کردن فایل وجود ندارد. توصیه می‌کنیم: (1) از رمز‌های عبوری استفاده کنید که به خاطر می‌سپارید. (2) رمز عبور را در یک مدیر رمز عبور ذخیره کنید. (3) قبل از محافظت، یک نسخه پشتیبان از فایل اصلی نگه دارید.', tr: 'Şifrenizi güvenli bir yere kaydedin! OptimaPDF şifreleri saklamaz ve onları kurtaramaz. Şifrenizi unutursanız dosyayı açmanın hiçbir yolu yoktur. Öneririz: (1) Hatırlayabileceğiniz şifreler kullanın. (2) Şifreyi bir şifre yöneticisine kaydedin. (3) Korumadan önce orijinal dosyanın bir yedeğini saklayın.', hi: 'अपना पासवर्ड एक सुरक्षित स्थान पर सहेजें! OptimaPDF पासवर्ड संग्रहीत नहीं करता है और उन्हें पुनर्प्राप्त नहीं कर सकता है। यदि आप अपना पासवर्ड भूल जाते हैं, तो फ़ाइल खोलने का कोई तरीका नहीं है। हम सलाह देते हैं: (1) ऐसे पासवर्ड का उपयोग करें जिन्हें आप याद रख सकते हैं। (2) पासवर्ड को पासवर्ड मैनेजर में सहेजें। (3) सुरक्षा से पहले मूल फ़ाइल का बैकअप रखें।', is: 'Vistaðu lykilorðið þitt á öruggum stað! OptimaPDF geymir ekki lykilorð og getur ekki endurheimt þau. Ef þú gleymir lykilorðinu er engin leið til að opna skrána. Við mælum með: (1) Notaðu lykilorð sem þú getur munað. (2) Vistaðu lykilorðið í lykilorðastjóra. (3) Haltu afriti af upprunalegu skránni áður en þú verndar.', it: 'Salva la password in un luogo sicuro! OptimaPDF non memorizza le password e non può recuperarle. Se dimentichi la password, non c\'è modo di aprire il file. Ti consigliamo di: (1) usare password che ricordi. (2) Salvare la password in un gestore di password. (3) Conservare una copia del file originale prima di proteggerlo.', ja: 'パスワードは安全な場所に保存してください！OptimaPDFはパスワードを保存せず、パスワードを復元することもできません。パスワードを忘れた場合、ファイルを開く方法はありません。お勧めの方法：（1）覚えやすいパスワードを使用してください。（2）パスワードマネージャーにパスワードを保存してください。（3）保護する前に元のファイルのバックアップを保存しておいてください。', zh: '请将密码保存在安全的地方！OptimaPDF不存储密码，也无法找回密码。如果您忘记了密码，就无法打开文件。我们建议：（1）使用您能记住的密码。（2）将密码保存在密码管理器中。（3）在保护之前备份原始文件。'},
      },
      { key: 'unlock-fail', href: '/unlock-pdf',
        q: { pl: 'Odblokowanie PDF nie działa — złe hasło?', en: 'Unlock doesn\'t work — wrong password?' , de: 'Entsperren funktioniert nicht – falsches Passwort?', es: '¿El desbloqueo no funciona: contraseña incorrecta?', pt: 'O desbloqueio não funciona — palavra-passe errada?', no: 'Fungerer ikke opplåsing — feil passord?', sv: 'Fungerar inte upplåsning — fel lösenord?', fr: 'Le déverrouillage ne fonctionne pas — mauvais mot de passe ?', ar: 'فتح القفل لا يعمل — كلمة مرور خاطئة؟', fa: 'باز کردن قفل کار نمی‌کند — رمز عبور اشتباه است؟', tr: 'Kilidi açma çalışmıyor — yanlış şifre mi?', hi: 'क्या अनलॉक काम नहीं करता है - गलत पासवर्ड?', is: 'Virkar aflæsingin ekki — rangt lykilorð?', it: 'Lo sblocco non funziona: password errata?', ja: 'ロック解除が機能しません。パスワードが間違っていますか？', zh: '解锁不起作用——密码错误？'},
        a: { pl: 'Odblokowanie wymaga podania poprawnego hasła. Jeśli hasło jest poprawne, ale odblokowanie nie działa, plik może używać starszego lub rzadkiego typu szyfrowania. W takim przypadku spróbuj otworzyć PDF w Adobe Reader, wpisz hasło, a następnie zapisz kopię bez zabezpieczeń — i tą kopię przetwarzaj dalej.', en: 'Unlocking requires the correct password. If the password is correct but unlocking doesn\'t work, the file may use an older or rare encryption type. In that case, try opening the PDF in Adobe Reader, enter the password, then save an unprotected copy — and process that copy further.' , de: 'Zum Entsperren ist das richtige Passwort erforderlich. Wenn das Passwort korrekt ist, das Entsperren aber nicht funktioniert, verwendet die Datei möglicherweise einen älteren oder seltenen Verschlüsselungstyp. Öffnen Sie in diesem Fall das PDF in Adobe Reader, geben Sie das Passwort ein, speichern Sie dann eine ungeschützte Kopie – und verarbeiten Sie diese Kopie weiter.', es: 'El desbloqueo requiere la contraseña correcta. Si la contraseña es correcta pero el desbloqueo no funciona, el archivo puede usar un tipo de cifrado antiguo o poco común. En ese caso, intente abrir el PDF en Adobe Reader, introduzca la contraseña, guarde una copia sin protección y procese esa copia.', pt: 'O desbloqueio exige a palavra-passe correta. Se a palavra-passe estiver correta, mas o desbloqueio não funcionar, o ficheiro pode utilizar um tipo de encriptação mais antigo ou raro. Nesse caso, tente abrir o PDF no Adobe Reader, introduza a palavra-passe, guarde uma cópia desprotegida — e processe essa cópia.', no: 'Opplåsing krever riktig passord. Hvis passordet er riktig, men opplåsing ikke fungerer, kan filen bruke en eldre eller sjelden krypteringstype. I så fall, prøv å åpne PDF-en i Adobe Reader, skriv inn passordet, lagre en ubeskyttet kopi — og behandle den kopien videre.', sv: 'Upplåsning kräver rätt lösenord. Om lösenordet är korrekt men upplåsning inte fungerar kan filen använda en äldre eller ovanlig krypteringstyp. I så fall, prova att öppna PDF-filen i Adobe Reader, ange lösenordet, spara en oskyddad kopia — och bearbeta den kopian vidare.', fr: 'Le déverrouillage nécessite le bon mot de passe. Si le mot de passe est correct mais que le déverrouillage ne fonctionne pas, le fichier peut utiliser un type de chiffrement ancien ou rare. Dans ce cas, essayez d\'ouvrir le PDF dans Adobe Reader, saisissez le mot de passe, enregistrez une copie non protégée — puis traitez cette copie.', ar: 'يتطلب فتح القفل كلمة المرور الصحيحة. إذا كانت كلمة المرور صحيحة ولكن فتح القفل لا يعمل، فقد يستخدم الملف نوع تشفير أقدم أو نادر. في هذه الحالة، جرّب فتح PDF في Adobe Reader، وأدخل كلمة المرور، ثم احفظ نسخة غير محمية — وقم بمعالجة هذه النسخة.', fa: 'باز کردن قفل به رمز عبور صحیح نیاز دارد. اگر رمز عبور صحیح است اما قفل باز نمی‌شود، ممکن است فایل از نوع رمزگذاری قدیمی یا نادر استفاده کند. در این صورت، سعی کنید PDF را در Adobe Reader باز کنید، رمز عبور را وارد کنید، سپس یک کپی بدون محافظت ذخیره کنید — و آن کپی را بیشتر پردازش کنید.', tr: 'Kilidi açmak doğru şifreyi gerektirir. Şifre doğruysa ancak kilit açılmıyorsa dosya eski veya nadir bir şifreleme türü kullanıyor olabilir. Bu durumda PDF\'yi Adobe Reader\'da açmayı deneyin, şifreyi girin, ardından korumasız bir kopya kaydedin — ve bu kopyayı daha sonra işleyin.', hi: 'अनलॉक करने के लिए सही पासवर्ड की आवश्यकता होती है। यदि पासवर्ड सही है लेकिन अनलॉक नहीं हो पाता है, तो फ़ाइल पुराने या दुर्लभ एन्क्रिप्शन प्रकार का उपयोग कर सकती है। उस स्थिति में, PDF को Adobe Reader में खोलने का प्रयास करें, पासवर्ड दर्ज करें, फिर एक असुरक्षित प्रति सहेजें - और उस प्रति को आगे प्रक्रिया करें।', is: 'Aflæsing krefst rétta lykilorðsins. Ef lykilorðið er rétt en aflæsingin virkar ekki getur skráin notað eldri eða sjaldgæfa dulkóðunargerð. Prófaðu þá að opna PDF-ið í Adobe Reader, slá inn lykilorðið og vista óverndað afrit — og vinnðu síðan áfram með það afrit.', it: 'Per sbloccare il file è necessaria la password corretta. Se la password è corretta ma lo sblocco non funziona, il file potrebbe utilizzare un tipo di crittografia vecchio o raro. In tal caso, prova ad aprire il PDF in Adobe Reader, inserisci la password, poi salva una copia non protetta: ed elabora ulteriormente quella copia.', ja: 'ロック解除には正しいパスワードが必要です。パスワードが正しいのにロック解除が機能しない場合、ファイルが古いまたは珍しい暗号化タイプを使用している可能性があります。その場合は、Adobe ReaderでPDFを開き、パスワードを入力して、保護されていないコピーを保存してみてください。その後、そのコピーをさらに処理してください。', zh: '解锁需要正确的密码。如果密码正确但解锁仍然无效，则文件可能使用了较旧或罕见的加密类型。在这种情况下，请尝试在Adobe Reader中打开PDF，输入密码，然后保存一份未加密的副本——并继续处理该副本。'},
      },
      { key: 'sign-nosign', href: '/sign-pdf',
        q: { pl: 'Podpis nie wyświetla się na stronie?', en: 'Signature doesn\'t appear on the page?' , de: 'Die Signatur erscheint nicht auf der Seite?', es: '¿La firma no aparece en la página?', pt: 'A assinatura não aparece na página?', no: 'Vises ikke signaturen på siden?', sv: 'Visas inte signaturen på sidan?', fr: 'La signature n\'apparaît pas sur la page ?', ar: 'لا يظهر التوقيع على الصفحة؟', fa: 'امضا در صفحه نمایش داده نمی‌شود؟', tr: 'İmza sayfada görünmüyor mu?', hi: 'क्या हस्ताक्षर पृष्ठ पर दिखाई नहीं देता है?', is: 'Birtist undirskriftin ekki á síðunni?', it: 'La firma non appare sulla pagina?', ja: '署名がページに表示されませんか？', zh: '签名没有显示在页面上？'},
        a: {
          ar: 'تحقق من: (1) الصفحات التي اخترتها: جميعها أو الأولى أو الأخيرة أو صفحة محددة. (2) أن الإحداثيات X/Y تقع داخل الصفحة؛ ويمكنك تجنب ذلك باختيار موضع سريع مثل أسفل اليمين. (3) التوقيع المرسوم أزرق ورفيع بقدر خطك، فإذا كان صعب الرؤية فارسمه أكبر أو استخدم توقيعًا نصيًا.',
          de: 'Prüfen Sie: (1) Welche Seiten Sie gewählt haben — alle, die erste, die letzte oder eine bestimmte. (2) Ob die X/Y-Koordinaten innerhalb der Seite liegen; eine Schnellposition wie unten rechts vermeidet das Problem. (3) Eine gezeichnete Unterschrift ist blau und so dünn wie Ihr Strich — ist sie schwer zu sehen, zeichnen Sie sie größer oder verwenden Sie eine Textunterschrift.',
          en: 'Check: (1) Which pages you chose — all, the first, the last or a specific one. (2) That the X/Y coordinates fall inside the page; a quick position such as bottom right avoids this. (3) A drawn signature is blue and as thin as your stroke — if it is hard to see, draw it larger or use a text signature.',
          es: 'Comprueba: (1) Qué páginas elegiste: todas, la primera, la última o una concreta. (2) Que las coordenadas X/Y estén dentro de la página; una posición rápida, como abajo a la derecha, lo evita. (3) Una firma dibujada es azul y tan fina como tu trazo: si apenas se ve, dibújala más grande o usa una firma de texto.',
          fa: 'بررسی کنید: (1) کدام صفحه‌ها را انتخاب کرده‌اید: همه، اولی، آخری یا صفحه‌ای مشخص. (2) آیا مختصات X/Y درون صفحه است؛ انتخاب یک جای سریع مانند پایین راست این مشکل را برطرف می‌کند. (3) امضای کشیده‌شده آبی و به نازکی خط شماست؛ اگر خوب دیده نمی‌شود، آن را بزرگ‌تر بکشید یا از امضای متنی استفاده کنید.',
          fr: 'Vérifiez : (1) Les pages choisies : toutes, la première, la dernière ou une page précise. (2) Que les coordonnées X/Y se trouvent dans la page ; une position rapide comme en bas à droite évite ce problème. (3) Une signature dessinée est bleue et aussi fine que votre tracé : si elle se voit mal, dessinez-la plus grande ou utilisez une signature texte.',
          hi: 'जाँचें: (1) आपने कौन-से पृष्ठ चुने — सभी, पहला, अंतिम या कोई विशेष पृष्ठ। (2) क्या X/Y निर्देशांक पृष्ठ के भीतर हैं; नीचे दाएँ जैसी त्वरित स्थिति से यह समस्या नहीं होती। (3) बनाया गया हस्ताक्षर नीला होता है और आपकी रेखा जितना पतला — अगर ठीक से न दिखे तो उसे बड़ा बनाएँ या टेक्स्ट हस्ताक्षर इस्तेमाल करें।',
          is: 'Athugaðu: (1) Hvaða síður þú valdir — allar, þá fyrstu, þá síðustu eða ákveðna síðu. (2) Að X/Y-hnitin séu innan síðunnar; flýtistaða eins og neðst til hægri kemur í veg fyrir vandann. (3) Teiknuð undirskrift er blá og jafn grönn og strokan þín — ef hún sést illa skaltu teikna hana stærri eða nota textaundirskrift.',
          it: 'Controlla: (1) Quali pagine hai scelto: tutte, la prima, l’ultima o una precisa. (2) Che le coordinate X/Y rientrino nella pagina; una posizione rapida, come in basso a destra, evita il problema. (3) Una firma disegnata è blu e sottile quanto il tuo tratto: se si vede poco, disegnala più grande o usa una firma di testo.',
          ja: '確認してください：(1) 選んだページ（全ページ、最初、最後、特定のページ）。(2) X/Y 座標がページ内に収まっているか。右下などのクイック位置を使えばこの問題を避けられます。(3) 描いたサインは青色で、線の太さは描いたとおりです。見えにくい場合は大きく描くか、テキストの署名を使ってください。',
          no: 'Sjekk: (1) Hvilke sider du valgte — alle, den første, den siste eller en bestemt side. (2) At X/Y-koordinatene ligger innenfor siden; en hurtigposisjon som nede til høyre unngår problemet. (3) En tegnet signatur er blå og like tynn som streken din — er den vanskelig å se, tegner du den større eller bruker en tekstsignatur.',
          pl: 'Sprawdź: (1) Które strony wybrałeś — wszystkie, pierwszą, ostatnią czy konkretną. (2) Czy współrzędne X/Y mieszczą się na stronie; szybka pozycja, np. prawy dolny róg, rozwiązuje ten problem. (3) Narysowany podpis jest niebieski i tak cienki jak Twoje pociągnięcie — jeśli słabo go widać, narysuj go większy albo użyj podpisu tekstowego.',
          pt: 'Verifique: (1) Que páginas escolheu: todas, a primeira, a última ou uma específica. (2) Se as coordenadas X/Y ficam dentro da página; uma posição rápida, como em baixo à direita, evita o problema. (3) Uma assinatura desenhada é azul e tão fina como o seu traço: se mal se vê, desenhe-a maior ou use uma assinatura de texto.',
          sv: 'Kontrollera: (1) Vilka sidor du valde — alla, den första, den sista eller en viss sida. (2) Att X/Y-koordinaterna ligger inom sidan; en snabbposition som nere till höger undviker problemet. (3) En ritad namnteckning är blå och lika tunn som ditt penseldrag — syns den dåligt, rita den större eller använd en textsignatur.',
          tr: 'Kontrol edin: (1) Hangi sayfaları seçtiğinizi — tümü, ilk, son veya belirli bir sayfa. (2) X/Y koordinatlarının sayfanın içinde olup olmadığını; sağ alt gibi hızlı bir konum bu sorunu önler. (3) Çizilmiş imza mavidir ve çizginiz kadar incedir; zor görünüyorsa daha büyük çizin veya metin imzası kullanın.',
          zh: '请检查：(1) 选择了哪些页面：全部、第一页、最后一页还是某一页。(2) X/Y 坐标是否在页面范围内；使用右下角等快速位置可避免这个问题。(3) 手绘签名为蓝色，粗细与你的笔画相同；如果看不清，请画大一些或改用文字签名。',
        },
      },
      { key: 'fillform-notinteractive', href: '/fill-form',
        q: { pl: 'Formularz PDF nie ma pól do wypełnienia?', en: 'The PDF form has no fillable fields?' , de: 'Das PDF-Formular hat keine ausfüllbaren Felder?', es: '¿El formulario PDF no tiene campos rellenables?', pt: 'O formulário PDF não tem campos preenchíveis?', no: 'Har ikke PDF-skjemaet utfyllbare felt?', sv: 'Har PDF-formuläret inga ifyllningsbara fält?', fr: 'Le formulaire PDF ne comporte aucun champ à remplir ?', ar: 'نموذج PDF لا يحتوي على حقول قابلة للتعبئة؟', fa: 'فرم PDF هیچ فیلد قابل پر کردن ندارد؟', tr: 'PDF formunda doldurulabilir alan yok mu?', hi: 'क्या PDF फ़ॉर्म में भरने योग्य फ़ील्ड नहीं हैं?', is: 'Hefur PDF-eyðublaðið engin fyllanleg reit?', it: 'Il modulo PDF non ha campi compilabili?', ja: 'PDFフォームに入力可能なフィールドがありませんか？', zh: 'PDF表单没有可填写的字段？'},
        a: { pl: 'Narzędzie wypełnia tylko interaktywne formularze AcroForm. Jeśli PDF wygląda jak formularz, ale nie ma pól, to prawdopodobnie jest to skan lub obraz — w takim przypadku użyj opcji edycji (dodaj tekst ręcznie) lub OCR, aby rozpoznać tekst. Niektóre formularze wypełniane w programie Adobe Reader mogą nie być rozpoznawane jako AcroForm.', en: 'The tool only fills interactive AcroForm forms. If the PDF looks like a form but has no fields, it\'s likely a scan or image — in that case, use the edit tool (add text manually) or OCR to recognize text. Some forms filled in Adobe Reader may not be recognized as AcroForm.' , de: 'Das Werkzeug füllt nur interaktive AcroForm-Formulare aus. Wenn das PDF wie ein Formular aussieht, aber keine Felder hat, handelt es sich wahrscheinlich um einen Scan oder ein Bild – verwenden Sie in diesem Fall das Bearbeitungswerkzeug (Text manuell hinzufügen) oder OCR, um Text zu erkennen. Einige in Adobe Reader ausgefüllte Formulare werden möglicherweise nicht als AcroForm erkannt.', es: 'La herramienta solo rellena formularios AcroForm interactivos. Si el PDF parece un formulario pero no tiene campos, probablemente sea un escaneo o una imagen: en ese caso, use la herramienta de edición (añada texto manualmente) o el OCR para reconocer el texto. Algunos formularios rellenados en Adobe Reader pueden no reconocerse como AcroForm.', pt: 'A ferramenta só preenche formulários AcroForm interativos. Se o PDF parecer um formulário, mas não tiver campos, provavelmente é uma digitalização ou uma imagem — nesse caso, utilize a ferramenta de edição (adicione texto manualmente) ou o OCR para reconhecer o texto. Alguns formulários preenchidos no Adobe Reader podem não ser reconhecidos como AcroForm.', no: 'Verktøyet fyller bare ut interaktive AcroForm-skjemaer. Hvis PDF-en ser ut som et skjema, men ikke har noen felt, er det sannsynligvis en skanning eller et bilde — i så fall, bruk redigeringsverktøyet (legg til tekst manuelt) eller OCR for å gjenkjenne tekst. Noen skjemaer som er fylt ut i Adobe Reader, blir kanskje ikke gjenkjent som AcroForm.', sv: 'Verktyget fyller endast i interaktiva AcroForm-formulär. Om PDF-filen ser ut som ett formulär men inte har några fält är det troligen en skanning eller en bild — i så fall, använd redigeringsverktyget (lägg till text manuellt) eller OCR för att känna igen text. Vissa formulär som fyllts i Adobe Reader kanske inte känns igen som AcroForm.', fr: 'L\'outil ne remplit que les formulaires AcroForm interactifs. Si le PDF ressemble à un formulaire mais ne comporte aucun champ, il s\'agit probablement d\'un scan ou d\'une image — dans ce cas, utilisez l\'outil de modification (ajoutez le texte manuellement) ou l\'OCR pour reconnaître le texte. Certains formulaires remplis dans Adobe Reader peuvent ne pas être reconnus comme AcroForm.', ar: 'تقوم الأداة فقط بتعبئة نماذج AcroForm التفاعلية. إذا كان ملف PDF يبدو كنموذج ولكنه لا يحتوي على حقول، فمن المحتمل أنه مسح ضوئي أو صورة — في هذه الحالة، استخدم أداة التعديل (أضف النص يدويًا) أو OCR للتعرف على النص. بعض النماذج المملوءة في Adobe Reader قد لا يتم التعرف عليها كـ AcroForm.', fa: 'این ابزار فقط فرم‌های تعاملی AcroForm را پر می‌کند. اگر PDF شبیه فرم به نظر می‌رسد اما فیلدی ندارد، احتمالاً اسکن یا تصویر است — در این صورت، از ابزار ویرایش استفاده کنید (متن را به صورت دستی اضافه کنید) یا از OCR برای تشخیص متن استفاده کنید. برخی از فرم‌هایی که در Adobe Reader پر شده‌اند ممکن است به عنوان AcroForm تشخیص داده نشوند.', tr: 'Araç yalnızca etkileşimli AcroForm formlarını doldurur. PDF bir forma benziyor ancak alan içermiyorsa büyük olasılıkla tarama veya görseldir — bu durumda düzenleme aracını kullanın (metni elle ekleyin) veya metni tanımak için OCR\'den yararlanın. Adobe Reader\'da doldurulmuş bazı formlar AcroForm olarak tanınmayabilir.', hi: 'उपकरण केवल इंटरैक्टिव AcroForm फ़ॉर्म भरता है। यदि PDF एक फ़ॉर्म जैसा दिखता है लेकिन उसमें कोई फ़ील्ड नहीं है, तो यह संभवतः एक स्कैन या छवि है - उस स्थिति में, संपादन उपकरण का उपयोग करें (टेक्स्ट मैन्युअल रूप से जोड़ें) या टेक्स्ट को पहचानने के लिए OCR का उपयोग करें। Adobe Reader में भरे गए कुछ फ़ॉर्म AcroForm के रूप में पहचाने नहीं जा सकते हैं।', is: 'Tólið fyllir aðeins út gagnvirk AcroForm-eyðublöð. Ef PDF-ið lítur út eins og eyðublað en hefur enga reiti er það líklega skönnun eða mynd — notaðu þá breytingartólið (bættu við texta handvirkt) eða OCR til að þekkja textann. Sum eyðublöð sem fyllt hafa verið út í Adobe Reader gætu ekki verið þekkt sem AcroForm.', it: 'Lo strumento compila solo i moduli AcroForm interattivi. Se il PDF sembra un modulo ma non ha campi, probabilmente è una scansione o un\'immagine: in tal caso, utilizza lo strumento di modifica (aggiungi testo manualmente) o l\'OCR per riconoscere il testo. Alcuni moduli compilati in Adobe Reader potrebbero non essere riconosciuti come AcroForm.', ja: 'このツールは、インタラクティブなAcroFormフォームのみを入力できます。PDFがフォームのように見えてもフィールドがない場合は、スキャンまたは画像である可能性が高いです。その場合は、編集ツール（テキストを手動で追加）またはOCRを使用してテキストを認識してください。Adobe Readerで入力した一部のフォームは、AcroFormとして認識されない場合があります。', zh: '该工具只能填写交互式AcroForm表单。如果PDF看起来像表单但没有字段，那么它很可能是扫描件或图像——在这种情况下，请使用编辑工具（手动添加文本）或OCR来识别文本。某些在Adobe Reader中填写的表单可能无法被识别为AcroForm。'},
      },
      { key: 'pdfa-error', href: '/to-pdfa',
        q: { pl: 'Konwersja do PDF/A zgłasza błąd?', en: 'PDF/A conversion reports an error?' , de: 'Die Konvertierung zu PDF/A meldet einen Fehler?', es: '¿La conversión a PDF/A informa de un error?', pt: 'A conversão para PDF/A apresenta um erro?', no: 'Rapporterer PDF/A-konverteringen en feil?', sv: 'Rapporterar PDF/A-konverteringen ett fel?', fr: 'La conversion PDF/A signale une erreur ?', ar: 'التحويل إلى PDF/A يبلغ عن خطأ؟', fa: 'تبدیل به PDF/A خطا گزارش می‌کند؟', tr: 'PDF/A dönüştürme hata mı bildiriyor?', hi: 'क्या PDF/A रूपांतरण त्रुटि की रिपोर्ट करता है?', is: 'Greinir PDF/A-umbreytingin frá villu?', it: 'La conversione in PDF/A segnala un errore?', ja: 'PDF/Aへの変換でエラーが報告されますか？', zh: 'PDF/A转换报错？'},
        a: { pl: 'Konwersja do PDF/A wykonuje "best-effort" — nie gwarantuje 100% zgodności ze standardem. Problemy mogą wystąpić dla plików z: (1) osadzonymi czcionkami bez licencji, (2) zaawansowanymi formularzami, (3) multimediami (audio, wideo). Mimo błędu plik może działać poprawnie w większości programów do archiwizacji.', en: 'PDF/A conversion is "best-effort" — it doesn\'t guarantee 100% standard compliance. Issues may occur for files with: (1) embedded fonts without license, (2) advanced forms, (3) multimedia (audio, video). Despite the error, the file may work correctly in most archiving programs.' , de: 'Die Konvertierung zu PDF/A ist eine „Best-Effort“-Konvertierung – sie garantiert keine 100%ige Konformität mit dem Standard. Probleme können bei Dateien auftreten mit: (1) eingebetteten Schriften ohne Lizenz, (2) erweiterten Formularen, (3) Multimedia (Audio, Video). Trotz des Fehlers kann die Datei in den meisten Archivierungsprogrammen korrekt funktionieren.', es: 'La conversión a PDF/A es de «mejor esfuerzo»: no garantiza una conformidad del 100 % con el estándar. Pueden surgir problemas con archivos que tengan: (1) fuentes incrustadas sin licencia, (2) formularios avanzados, (3) multimedia (audio, vídeo). A pesar del error, el archivo puede funcionar correctamente en la mayoría de los programas de archivado.', pt: 'A conversão para PDF/A é «best-effort» — não garante 100 % de conformidade com o padrão. Podem ocorrer problemas em ficheiros com: (1) fontes incorporadas sem licença, (2) formulários avançados, (3) multimédia (áudio, vídeo). Apesar do erro, o ficheiro pode funcionar corretamente na maioria dos programas de arquivo.', no: 'PDF/A-konvertering er «best-effort» — den garanterer ikke 100 % samsvar med standarden. Problemer kan oppstå for filer med: (1) innebygde skrifttyper uten lisens, (2) avanserte skjemaer, (3) multimedia (lyd, video). Til tross for feilen kan filen fungere riktig i de fleste arkiveringsprogrammer.', sv: 'PDF/A-konvertering är ”best-effort” — den garanterar inte 100% överensstämmelse med standarden. Problem kan uppstå för filer med: (1) inbäddade teckensnitt utan licens, (2) avancerade formulär, (3) multimedia (ljud, video). Trots felet kan filen fungera korrekt i de flesta arkiveringsprogram.', fr: 'La conversion PDF/A est « best-effort » — elle ne garantit pas une conformité à 100% avec la norme. Des problèmes peuvent survenir pour les fichiers : (1) avec des polices intégrées sans licence, (2) avec des formulaires avancés, (3) avec du multimédia (audio, vidéo). Malgré l\'erreur, le fichier peut fonctionner correctement dans la plupart des programmes d\'archivage.', ar: 'التحويل إلى PDF/A هو "best-effort" — لا يضمن الامتثال بنسبة 100% للمعيار. قد تحدث مشاكل للملفات التي تحتوي على: (1) خطوط مدمجة بدون ترخيص، (2) نماذج متقدمة، (3) وسائط متعددة (صوت، فيديو). على الرغم من الخطأ، قد يعمل الملف بشكل صحيح في معظم برامج الأرشفة.', fa: 'تبدیل به PDF/A "best-effort" است — انطباق 100% با استاندارد را تضمین نمی‌کند. ممکن است برای فایل‌های دارای این موارد مشکل ایجاد شود: (1) فونت‌های جاسازی شده‌ی بدون مجوز، (2) فرم‌های پیشرفته، (3) چندرسانه‌ای (صدا، ویدیو). با وجود خطا، فایل ممکن است در اکثر برنامه‌های بایگانی به درستی کار کند.', tr: 'PDF/A dönüştürme "best-effort" türündedir — %100 standart uyumluluğu garanti etmez. Şu özelliklere sahip dosyalarda sorunlar oluşabilir: (1) lisanssız gömülü yazı tipleri, (2) gelişmiş formlar, (3) çoklu ortam (ses, video). Hataya rağmen dosya çoğu arşivleme programında doğru çalışabilir.', hi: 'PDF/A रूपांतरण "best-effort" है - यह 100% मानक अनुपालन की गारंटी नहीं देता है। निम्नलिखित वाली फ़ाइलों के लिए समस्याएँ हो सकती हैं: (1) बिना लाइसेंस के एम्बेड किए गए फ़ॉन्ट, (2) उन्नत फ़ॉर्म, (3) मल्टीमीडिया (ऑडियो, वीडियो)। त्रुटि के बावजूद, फ़ाइल अधिकांश अभिलेखीकरण प्रोग्रामों में सही ढंग से काम कर सकती है।', is: 'PDF/A-umbreyting er "best-effort" — hún tryggir ekki 100% samræmi við staðalinn. Vandamál geta komið upp fyrir skrár með: (1) innfelldar leturgerðir án leyfis, (2) háþróuð eyðublöð, (3) margmiðlun (hljóð, myndbönd). Þrátt fyrir villuna getur skráin virkað rétt í flestum skjalavarðarforritum.', it: 'La conversione in PDF/A è «best-effort»: non garantisce la conformità al 100% con lo standard. I problemi possono verificarsi per file con: (1) caratteri incorporati senza licenza, (2) moduli avanzati, (3) contenuti multimediali (audio, video). Nonostante l\'errore, il file potrebbe funzionare correttamente nella maggior parte dei programmi di archiviazione.', ja: 'PDF/Aへの変換は「ベストエフォート」方式で、100%の標準準拠を保証するものではありません。次のようなファイルで問題が発生する場合があります：（1）ライセンスのない埋め込みフォント、（2）高度なフォーム、（3）マルチメディア（音声、動画）。エラーが発生しても、ファイルはほとんどのアーカイブプログラムで正しく動作する可能性があります。', zh: 'PDF/A转换采用“尽力而为”的方式——不保证100%符合标准。对于带有以下内容的文件可能出现问题：（1）无许可证的内嵌字体，（2）高级表单，（3）多媒体（音频、视频）。尽管报错，文件在大多数归档程序中仍可能正常工作。'},
      },
    ],
  },
  {
    key: 'ai', icon: 'sparkle',
    label: { pl: 'Narzędzia AI', en: 'AI Tools' , de: 'KI-Werkzeuge', es: 'Herramientas de IA', pt: 'Ferramentas de IA', no: 'AI-verktøy', sv: 'AI-verktyg', fr: 'Outils IA', ar: 'أدوات الذكاء الاصطناعي', fa: 'ابزارهای هوش مصنوعی', tr: 'Yapay Zeka Araçları', hi: 'AI उपकरण', is: 'AI verkfæri', it: 'Strumenti AI', ja: 'AIツール', zh: 'AI工具'},
    items: [
      { key: 'aikey', href: '/ai-chat',
        q: { pl: 'Czy narzędzia AI wymagają klucza API albo konta?', en: 'Do the AI tools need an API key or an account?', de: 'Brauchen die KI-Werkzeuge einen API-Schlüssel oder ein Konto?', es: '¿Las herramientas de IA necesitan una clave de API o una cuenta?', fr: 'Les outils IA nécessitent-ils une clé API ou un compte ?', it: 'Gli strumenti AI richiedono una chiave API o un account?', pt: 'As ferramentas de IA precisam de chave de API ou de conta?', sv: 'Behöver AI-verktygen en API-nyckel eller ett konto?', no: 'Trenger AI-verktøyene en API-nøkkel eller en konto?', is: 'Þurfa AI-verkfærin API-lykil eða aðgang?', tr: 'AI araçları için API anahtarı ya da hesap gerekir mi?', ja: 'AIツールにはAPIキーやアカウントが必要ですか？', zh: 'AI 工具需要 API 密钥或账户吗？', hi: 'क्या AI टूल के लिए API कुंजी या खाता चाहिए?', ar: 'هل تحتاج أدوات الذكاء الاصطناعي إلى مفتاح API أو حساب؟', fa: 'آیا ابزارهای هوش مصنوعی به کلید API یا حساب کاربری نیاز دارند؟' },
        a: { pl: 'Nie. Czat AI, AI Streszczenie i AI Tłumacz działają bez klucza i bez rejestracji — zapytania do serwisu AI wysyła nasz serwer. Każdy może wysłać do 15 zapytań AI na dobę; gdy limit się wyczerpie, strona podaje, za ile godzin można spróbować ponownie.', en: 'No. AI Chat, AI Summary and AI Translate work with no key and no sign-up — our server sends the requests to the AI service. Anyone can make up to 15 AI requests a day; when the limit is used up, the page tells you in how many hours you can try again.', de: 'Nein. KI-Chat, KI-Zusammenfassung und KI-Übersetzer funktionieren ohne Schlüssel und ohne Anmeldung — die Anfragen an den KI-Dienst sendet unser Server. Jeder kann bis zu 15 KI-Anfragen pro Tag stellen; ist das Limit erreicht, zeigt die Seite an, in wie vielen Stunden du es wieder versuchen kannst.', es: 'No. El chat, el resumen y el traductor con IA funcionan sin clave y sin registro: las consultas al servicio de IA las envía nuestro servidor. Cualquiera puede hacer hasta 15 consultas de IA al día; cuando se agota el límite, la página indica dentro de cuántas horas puedes volver a intentarlo.', fr: 'Non. Le chat, le résumé et le traducteur IA fonctionnent sans clé et sans inscription : c’est notre serveur qui envoie les requêtes au service d’IA. Chacun peut envoyer jusqu’à 15 requêtes IA par jour ; une fois la limite atteinte, la page indique dans combien d’heures vous pourrez réessayer.', it: 'No. Chat, riassunto e traduttore AI funzionano senza chiave e senza registrazione: le richieste al servizio AI le invia il nostro server. Chiunque può inviare fino a 15 richieste AI al giorno; quando il limite è esaurito, la pagina indica tra quante ore puoi riprovare.', pt: 'Não. O chat, o resumo e o tradutor com IA funcionam sem chave e sem registo: é o nosso servidor que envia os pedidos ao serviço de IA. Qualquer pessoa pode fazer até 15 consultas de IA por dia; quando o limite se esgota, a página indica dentro de quantas horas pode tentar de novo.', sv: 'Nej. AI-chatt, AI-sammanfattning och AI-översättare fungerar utan nyckel och utan registrering — det är vår server som skickar förfrågningarna till AI-tjänsten. Alla kan skicka upp till 15 AI-förfrågningar per dag; när gränsen är nådd visar sidan om hur många timmar du kan försöka igen.', no: 'Nei. AI-chat, AI-sammendrag og AI-oversetter fungerer uten nøkkel og uten registrering — det er serveren vår som sender forespørslene til AI-tjenesten. Alle kan sende opptil 15 AI-forespørsler per dag; når grensen er nådd, viser siden om hvor mange timer du kan prøve igjen.', is: 'Nei. AI-spjall, AI-samantekt og AI-þýðandi virka án lykils og án skráningar — þjónninn okkar sendir fyrirspurnirnar til gervigreindarþjónustunnar. Allir geta sent allt að 15 AI-fyrirspurnir á dag; þegar markinu er náð sýnir síðan eftir hve margar klukkustundir má reyna aftur.', tr: 'Hayır. AI Sohbet, AI Özet ve AI Çeviri anahtar ve kayıt olmadan çalışır — istekleri yapay zekâ hizmetine sunucumuz gönderir. Herkes günde en fazla 15 AI isteği gönderebilir; sınır dolduğunda sayfa kaç saat sonra yeniden deneyebileceğini gösterir.', ja: 'いいえ。AIチャット、AI要約、AI翻訳はキーも登録も不要です。AIサービスへのリクエストは当サイトのサーバーが送ります。1日に最大15回までリクエストでき、上限に達すると、何時間後に再試行できるかがページに表示されます。', zh: '不需要。AI 聊天、AI 摘要和 AI 翻译无需密钥，也无需注册——向 AI 服务发送请求的是我们的服务器。每人每天最多可发送 15 次 AI 请求；达到上限后，页面会显示几小时后可以重试。', hi: 'नहीं। AI चैट, AI सारांश और AI अनुवाद बिना कुंजी और बिना पंजीकरण के काम करते हैं — AI सेवा को अनुरोध हमारा सर्वर भेजता है। कोई भी प्रतिदिन अधिकतम 15 AI अनुरोध भेज सकता है; सीमा पूरी होने पर पेज बताता है कि कितने घंटे बाद फिर कोशिश कर सकते हैं।', ar: 'لا. تعمل الدردشة والتلخيص والترجمة بالذكاء الاصطناعي دون مفتاح ودون تسجيل، إذ يرسل خادمنا الطلبات إلى خدمة الذكاء الاصطناعي. يمكن لأي شخص إرسال ما يصل إلى 15 طلبًا يوميًا، وعند نفاد الحد تخبرك الصفحة بعد كم ساعة يمكنك المحاولة مجددًا.', fa: 'خیر. چت، خلاصه و مترجم هوش مصنوعی بدون کلید و بدون ثبت‌نام کار می‌کنند و درخواست‌ها را سرور ما به سرویس هوش مصنوعی می‌فرستد. هر کس می‌تواند روزانه تا 15 درخواست بفرستد؛ وقتی سقف پر شود، صفحه می‌گوید چند ساعت دیگر می‌توانید دوباره تلاش کنید.' },
      },
      { key: 'ai-slow', href: '/ai-chat',
        q: { pl: 'AI odpowiada bardzo wolno?', en: 'AI responds very slowly?' , de: 'KI antwortet sehr langsam?', es: '¿La IA responde muy lentamente?', pt: 'A IA responde muito lentamente?', no: 'Svarer AI veldig sakte?', sv: 'Svarar AI mycket långsamt?', fr: 'L\'IA répond très lentement ?', ar: 'الذكاء الاصطناعي يستجيب ببطء شديد؟', fa: 'هوش مصنوعی خیلی کند پاسخ می‌دهد؟', tr: 'Yapay zeka çok yavaş mı yanıt veriyor?', hi: 'क्या AI बहुत धीरे प्रतिक्रिया देता है?', is: 'Svarar gervigreindin mjög hægt?', it: 'L\'intelligenza artificiale risponde molto lentamente?', ja: 'AIの応答が非常に遅いですか？', zh: 'AI响应非常慢？'},
        a: { pl: 'Czas odpowiedzi zależy głównie od długości tekstu — streszczenie albo tłumaczenie długiego dokumentu trwa dłużej niż pytanie w czacie — a także od obciążenia serwisu AI i Twojego połączenia. Jeśli czekasz bardzo długo, spróbuj z krótszym fragmentem, np. po wyodrębnieniu potrzebnych stron.', en: 'Response time depends mainly on the length of the text — summarising or translating a long document takes longer than a chat question — and on how busy the AI service is and on your connection. If you wait very long, try a shorter part, for example after extracting the pages you need.', de: 'Die Antwortzeit hängt vor allem von der Textlänge ab — eine Zusammenfassung oder Übersetzung eines langen Dokuments dauert länger als eine Chatfrage — sowie von der Auslastung des KI-Dienstes und deiner Verbindung. Wenn du sehr lange wartest, versuche es mit einem kürzeren Teil, zum Beispiel nach dem Extrahieren der benötigten Seiten.', es: 'El tiempo de respuesta depende sobre todo de la longitud del texto (resumir o traducir un documento largo tarda más que una pregunta en el chat), además de la carga del servicio de IA y de tu conexión. Si esperas mucho, prueba con una parte más corta, por ejemplo después de extraer las páginas que necesitas.', fr: 'Le temps de réponse dépend surtout de la longueur du texte (résumer ou traduire un long document prend plus de temps qu’une question dans le chat), ainsi que de la charge du service d’IA et de votre connexion. Si l’attente est très longue, essayez avec une partie plus courte, par exemple après avoir extrait les pages utiles.', it: 'Il tempo di risposta dipende soprattutto dalla lunghezza del testo (riassumere o tradurre un documento lungo richiede più tempo di una domanda in chat), oltre che dal carico del servizio AI e dalla tua connessione. Se l’attesa è molto lunga, prova con una parte più breve, per esempio dopo aver estratto le pagine che ti servono.', pt: 'O tempo de resposta depende sobretudo do comprimento do texto (resumir ou traduzir um documento longo demora mais do que uma pergunta no chat), além da carga do serviço de IA e da sua ligação. Se esperar muito, experimente com uma parte mais curta, por exemplo depois de extrair as páginas de que precisa.', sv: 'Svarstiden beror främst på textens längd — att sammanfatta eller översätta ett långt dokument tar längre tid än en chattfråga — samt på hur belastad AI-tjänsten är och på din anslutning. Om du väntar mycket länge, prova med en kortare del, till exempel efter att ha extraherat de sidor du behöver.', no: 'Svartiden avhenger mest av tekstens lengde — et sammendrag eller en oversettelse av et langt dokument tar lengre tid enn et chatspørsmål — og av hvor travel AI-tjenesten er og av tilkoblingen din. Hvis du venter veldig lenge, prøv med en kortere del, for eksempel etter å ha hentet ut sidene du trenger.', is: 'Svartíminn ræðst einkum af lengd textans — samantekt eða þýðing langs skjals tekur lengri tíma en spurning í spjallinu — og af álagi á gervigreindarþjónustuna og tengingunni þinni. Ef biðin er mjög löng skaltu prófa styttri hluta, til dæmis eftir að hafa dregið út síðurnar sem þú þarft.', tr: 'Yanıt süresi en çok metnin uzunluğuna bağlıdır — uzun bir belgeyi özetlemek ya da çevirmek bir sohbet sorusundan uzun sürer — ayrıca yapay zekâ hizmetinin yoğunluğuna ve bağlantına. Çok uzun beklersen daha kısa bir bölümle dene, örneğin ihtiyacın olan sayfaları ayıkladıktan sonra.', ja: '応答時間は主にテキストの長さで決まります。長い文書の要約や翻訳は、チャットの質問より時間がかかります。AIサービスの混雑状況や通信環境にも左右されます。待ち時間が非常に長い場合は、必要なページを抽出するなどして短い部分で試してください。', zh: '响应时间主要取决于文本长度——为长文档生成摘要或翻译比在聊天中提问耗时更长——也取决于 AI 服务的繁忙程度和你的网络。如果等待时间很长，请改用较短的部分，例如先提取所需页面。', hi: 'जवाब का समय मुख्य रूप से टेक्स्ट की लंबाई पर निर्भर करता है — लंबे दस्तावेज़ का सारांश या अनुवाद चैट के सवाल से ज़्यादा समय लेता है — और AI सेवा की व्यस्तता व आपके कनेक्शन पर भी। अगर बहुत देर लगे, तो छोटे हिस्से से कोशिश करें, जैसे ज़रूरी पेज अलग करने के बाद।', ar: 'يعتمد وقت الاستجابة أساسًا على طول النص، فتلخيص مستند طويل أو ترجمته يستغرق وقتًا أطول من سؤال في الدردشة، كما يعتمد على ضغط خدمة الذكاء الاصطناعي وعلى اتصالك. إذا طال الانتظار كثيرًا، فجرّب جزءًا أقصر، مثلًا بعد استخراج الصفحات التي تحتاجها.', fa: 'زمان پاسخ بیشتر به طول متن بستگی دارد؛ خلاصه یا ترجمهٔ یک سند طولانی بیشتر از یک سؤال در چت طول می‌کشد. شلوغی سرویس هوش مصنوعی و اتصال شما هم اثر دارند. اگر خیلی منتظر ماندید، با بخش کوتاه‌تری امتحان کنید، مثلاً پس از جدا کردن صفحه‌های لازم.' },
      },
      { key: 'ai-wrong', href: '/ai-summary',
        q: { pl: 'AI podaje niepoprawne informacje?', en: 'AI gives incorrect information?' , de: 'KI liefert falsche Informationen?', es: '¿La IA ofrece información incorrecta?', pt: 'A IA fornece informações incorretas?', no: 'Gir AI feil informasjon?', sv: 'Ger AI felaktig information?', fr: 'L\'IA donne des informations incorrectes ?', ar: 'الذكاء الاصطناعي يعطي معلومات غير صحيحة؟', fa: 'هوش مصنوعی اطلاعات نادرست می‌دهد؟', tr: 'Yapay zeka yanlış bilgi mi veriyor?', hi: 'क्या AI गलत जानकारी देता है?', is: 'Gefur gervigreindin rangar upplýsingar?', it: 'L\'intelligenza artificiale fornisce informazioni errate?', ja: 'AIが誤った情報を提供しますか？', zh: 'AI提供的信息不正确？'},
        a: { pl: 'Modele AI mogą się mylić lub "halucynować" — podawać informacje, które brzmią wiarygodnie, ale są nieprawdziwe. Zawsze weryfikuj odpowiedzi AI z oryginalnym dokumentem. AI najlepiej sprawdza się w: streszczaniu, wyszukiwaniu konkretnych informacji i generowaniu podsumowań. Nie ufaj AI w 100% przy ważnych dokumentach.', en: 'AI models can make mistakes or "hallucinate" — provide information that sounds plausible but is incorrect. Always verify AI answers against the original document. AI works best for: summarizing, finding specific information and generating overviews. Don\'t trust AI 100% for important documents.' , de: 'KI-Modelle können Fehler machen oder „halluzinieren“ – Informationen liefern, die plausibel klingen, aber falsch sind. Überprüfen Sie KI-Antworten immer am Originaldokument. KI funktioniert am besten beim Zusammenfassen, Finden bestimmter Informationen und Erstellen von Übersichten. Vertrauen Sie bei wichtigen Dokumenten nicht zu 100 % der KI.', es: 'Los modelos de IA pueden cometer errores o «alucinar»: ofrecer información que parece plausible pero es incorrecta. Verifique siempre las respuestas de la IA con el documento original. La IA funciona mejor para: resumir, encontrar información específica y generar resúmenes. No confíe al 100 % en la IA para documentos importantes.', pt: 'Os modelos de IA podem cometer erros ou «alucinar» — fornecer informações que parecem plausíveis, mas são incorretas. Verifique sempre as respostas da IA em relação ao documento original. A IA funciona melhor para: resumir, encontrar informações específicas e gerar visões gerais. Não confie 100 % na IA para documentos importantes.', no: 'AI-modeller kan gjøre feil eller «hallusinere» — gi informasjon som høres plausibel ut, men som er feil. Kontroller alltid AI-svarene mot originaldokumentet. AI fungerer best for: å oppsummere, finne spesifikk informasjon og generere oversikter. Stol ikke 100 % på AI for viktige dokumenter.', sv: 'AI-modeller kan göra fel eller ”hallucinera” — ge information som låter trovärdig men som är felaktig. Kontrollera alltid AI-svaren mot originaldokumentet. AI fungerar bäst för: att sammanfatta, hitta specifik information och generera översikter. Lita inte 100% på AI för viktiga dokument.', fr: 'Les modèles IA peuvent se tromper ou « halluciner » — fournir des informations qui semblent plausibles mais qui sont incorrectes. Vérifiez toujours les réponses IA par rapport au document original. L\'IA fonctionne le mieux pour : résumer, trouver des informations spécifiques et générer des aperçus. N\'accordez pas 100% de confiance à l\'IA pour les documents importants.', ar: 'يمكن لنماذج الذكاء الاصطناعي أن ترتكب أخطاء أو "تهلوس" — تقديم معلومات تبدو معقولة ولكنها غير صحيحة. تحقق دائمًا من إجابات الذكاء الاصطناعي مقابل المستند الأصلي. يعمل الذكاء الاصطناعي بشكل أفضل في: التلخيص، والعثور على معلومات محددة، وإنشاء نظرات عامة. لا تثق بالذكاء الاصطناعي بنسبة 100% في المستندات المهمة.', fa: 'مدل‌های هوش مصنوعی ممکن است اشتباه کنند یا "توهم بزنند" — اطلاعاتی ارائه دهند که قابل قبول به نظر می‌رسد اما نادرست است. همیشه پاسخ‌های هوش مصنوعی را با سند اصلی بررسی کنید. هوش مصنوعی برای این موارد بهترین عملکرد را دارد: خلاصه‌سازی، یافتن اطلاعات خاص و تولید نمای کلی. برای اسناد مهم، 100% به هوش مصنوعی اعتماد نکنید.', tr: 'Yapay zeka modelleri hata yapabilir veya "halüsinasyon görebilir" — makul görünen ancak yanlış olan bilgiler sunabilir. Yapay zeka yanıtlarını her zaman orijinal belgeyle karşılaştırın. Yapay zeka en iyi şu işlerde çalışır: özet çıkarma, belirli bilgi bulma ve genel bakış oluşturma. Önemli belgeler için yapay zekaya %100 güvenmeyin.', hi: 'AI मॉडल गलतियाँ कर सकते हैं या "hallucinate" - प्रशंसनीय लगने वाली लेकिन गलत जानकारी प्रदान कर सकते हैं। AI उत्तरों को हमेशा मूल दस्तावेज़ के विरुद्ध सत्यापित करें। AI इन कार्यों के लिए सबसे अच्छा काम करता है: सारांश बनाना, विशिष्ट जानकारी खोजना और अवलोकन उत्पन्न करना। महत्वपूर्ण दस्तावेज़ों के लिए AI पर 100% भरोसा न करें।', is: 'Gervigreindarlíkön geta gert mistök eða "ofséð" — veitt upplýsingar sem hljóma trúverðugar en eru rangar. Sannreyndu alltaf svör gervigreindarinnar gegn upprunalega skjalinu. Gervigreind virkar best við: að draga saman, finna sérstakar upplýsingar og búa til yfirlit. Treystu ekki gervigreindinni 100% fyrir mikilvæg skjöl.', it: 'I modelli di intelligenza artificiale possono commettere errori o «allucinare»: fornire informazioni che sembrano plausibili ma non sono corrette. Verifica sempre le risposte dell\'intelligenza artificiale rispetto al documento originale. L\'intelligenza artificiale funziona meglio per: riassumere, trovare informazioni specifiche e generare panoramiche. Non fidarti al 100% dell\'intelligenza artificiale per documenti importanti.', ja: 'AIモデルは間違いを犯したり「幻覚」を起こしたりすることがあります。もっともらしく聞こえるが正しくない情報を提供することがあります。AIの回答は常に元のドキュメントと照合してください。AIは、要約、特定の情報の検索、概要の生成に最適です。重要なドキュメントでは、AIを100%信頼しないでください。', zh: 'AI模型可能会出错或“幻觉”——提供听起来合理但实际错误的信息。请始终对照原始文档核实AI的回答。AI最适合：总结、查找特定信息和生成概述。对于重要文档，请勿100%信任AI。'},
      },
    ],
  },
];
